import type { Client as SSHClient, ClientChannel } from "ssh2";

export interface ColumnDefinition {
  type: string | null;
  length?: number;
  allowNull?: boolean;
  unique?: boolean;
  /**
   * Real DB name of a NON-PRIMARY unique index this column participates in, from introspection.
   * Composite members share one name; `undefined` for inferred uniques. Never guessed: MySQL
   * auto-names a unique after its column, so a synthesised name would not match `DROP INDEX`.
   */
  uniqueName?: string;
  index?: boolean;
  pseudounique?: boolean;
  categorical?: boolean;
  singleValue?: boolean;
  primary?: boolean;
  autoIncrement?: boolean;
  default?: any;
  /**
   * DDL default EXPRESSION from the catalog. Kept separate from `default`, which doubles as the
   * literal `getInsertValues` substitutes for a missing cell: binding a DDL expression as a row
   * value would store the expression text verbatim (A3).
   */
  ddlDefault?: any;
  decimal?: number;
  calculated?: boolean;
  updatedCalculated?: boolean;
  calculatedDefault?: any;
  previousType?: string;
  tableName?: string[];
}

export type MetadataHeader = Record<string, ColumnDefinition>;

/**
 * Per-call options for `autoSQL`.
 *
 * `assumeSchema` (A-4) skips per-value inference for declared columns. `existingSchema` (N1) skips
 * live introspection, and must be autosql's own last resolved schema rather than a bare spec: a
 * baseline missing managed columns (`dwh_*`, surrogate) would make autosql re-ADD them. Pass it only
 * in steady state; drop it on load error or detected drift.
 */
export interface AutoSQLOptions {
  assumeSchema?: MetadataHeader;
  existingSchema?: MetadataHeader;
}

/** Options for `openStream` (see `AutoSQLHandler.openStream`). */
export interface OpenStreamOptions {
  /**
   * Opt in to staging that survives between runs. Identifies the load SESSION, not one run of it:
   * a run or attempt id would hand every retry a fresh table, so resuming would silently become
   * restarting. ⚠ One writer per key — autosql does not serialise them.
   * See README, "Resuming a stream across runs".
   */
  sessionKey?: string;
}

/** One target table's slice of an `autoSQL` preview (see `Database.preview`). */
export interface TablePreview {
  table: string;
  /** What a real load would do to this table. */
  action: 'create' | 'alter' | 'noop';
  /** Schema inferred from the data, with managed columns applied (dwh_* timestamps, surrogate key). */
  inferredSchema: MetadataHeader;
  /** The live table's current schema, or `null` if it does not exist yet. */
  currentSchema: MetadataHeader | null;
  /** The diff that would be applied (`null` on `create`). */
  changes: AlterTableChanges | null;
  /** The exact CREATE/ALTER statement(s) a real load would execute — preview runs none of them. */
  ddl: string[];
  /** Changes autosql would NOT apply without opting in (e.g. dropping a column needs `deleteColumns`). */
  blockedChanges: string[];
}

/**
 * What an `autoSQL` load WOULD do, computed without writing anything. Contrast with `safeMode`,
 * which runs the load but skips DDL.
 */
export interface AutoSQLPreview {
  /** One entry per target table (usually one; more when `autoSplit` / nested extraction apply). */
  tables: TablePreview[];
  /** Effective thousands/decimal separators (from `numberFormat`, explicit config, or auto-detection); omitted when the default heuristic applies. */
  numberFormat?: { thousands: string; decimal: string };
  /** Number of input rows. */
  rowCount: number;
}


export type supportedDialects = "mysql" | "pgsql" | "sqlserver";

export interface AlterTableChanges {
  addColumns: MetadataHeader;
  modifyColumns: MetadataHeader;
  dropColumns: string[];
  renameColumns: { oldName: string; newName: string }[];
  nullableColumns: string[];
  noLongerUnique: string[];
  primaryKeyChanges: string[];
}
  
export interface DatabaseConfig {
      sqlDialect: supportedDialects;
      host?: string;
      user?: string;
      password?: string;
      database?: string;
      port?: number;
      schema?: string;
      table?: string;
      /**
       * Max connections in the driver pool. Default 5. Raise for parallel/worker loads so pool
       * acquisition does not serialise; keep under the server's own limit and size against `maxWorkers`.
       */
      connectionLimit?: number;

      metaData?: {
        [tableName: string]: MetadataHeader;
      };
      existingMetaData?: {
        [tableName: string]: MetadataHeader;
      };
      updatePrimaryKey?: boolean;
      primaryKey?: string[];

      /**
       * Add an auto-increment surrogate key when the dataset has no natural one, so the table can be
       * created and Postgres upserts have a conflict target. Off by default. The key is unique per
       * physical insert, so every ingest APPENDS: `insertType: "UPDATE"` never matches an existing
       * row. Not compatible with `addHistory`, `addNested`, or `autoSplit`.
       */
      surrogateKey?: boolean;
      /** Column name for the surrogate key (see `surrogateKey`). Defaults to `"autosql_id"`. */
      surrogateKeyColumn?: string;
      engine?: string;
      charset?: string;
      collate?: string;
      encoding?: string;

      /**
       * MySQL only, off by default. Converts text columns on a PRE-EXISTING table to `charset`, so
       * externally-created 3-byte `utf8` columns accept 4-byte characters. Connection-charset pinning
       * and new-table defaults do not fix an existing column; this does. Best-effort: a failed
       * CONVERT (e.g. an over-long index) is logged and skipped. No-op on Postgres.
       */
      upgradeCharset?: boolean;

      pseudoUnique?: number;
      categorical?: number;
      autoIndexing?: boolean;
      /**
       * Infer `UNIQUE` constraints from the data (default `true`). Set `false` when one batch's
       * distinctness says nothing about the real key. Wins over `inferAdditionalUniques`; primary-key,
       * index and pseudounique prediction are unaffected.
       */
      inferUnique?: boolean;
      /**
       * Infer uniques beyond a new keyless table (default `true`): beside an explicit `primaryKey`,
       * and on an existing table. Set `false` for composite keys, because on MySQL a stray
       * `UNIQUE(id)` beside `PRIMARY KEY (conn, id)` makes `ON DUPLICATE KEY UPDATE` overwrite
       * another key's row. `inferUnique: false` wins over this.
       */
      inferAdditionalUniques?: boolean;
      /**
       * Cap on inferred `decimal` scale. Unset (default) stores at the full scale the data needs, up
       * to the dialect limit, so there is no silent precision loss. A value past the cap is ROUNDED
       * with a warning, unless `decimalToVarchar` is on.
       */
      decimalMaxLength?: number;
      /**
       * Store a decimal as text when its true scale exceeds the cap, keeping the exact value instead
       * of rounding. Off by default. Use when exact values matter more than SQL arithmetic.
       */
      decimalToVarchar?: boolean;
      maxKeyLength?: number;
      /**
       * Cap the auto-detected composite primary key (default 4). The search is O(2^N) in candidate
       * columns without a cap, which can hang on a wide table with no natural key. Raise only to
       * auto-detect a genuine 5+ column key.
       */
      maxCompositeKeyColumns?: number;
      maxVarcharLength?: number,

      sampling?: number;
      samplingMinimum?: number;

      insertType?: "UPDATE" | "INSERT";
      insertStack?: number;
      /**
       * Populate via the dialect's bulk-copy mechanism instead of parameterised INSERT. Off by
       * default. Requires `useStagingInsert`; upsert is preserved by the unchanged merge step. Falls
       * back to INSERT on error so a bad row still surfaces a clear message. Postgres needs
       * `pg-copy-streams`.
       */
      bulkLoad?: boolean;

      safeMode?: boolean;
      deleteColumns?: boolean;

      /**
       * Allow autosql to DROP a UNIQUE constraint that incoming data would violate. Default `false`:
       * the constraint is kept and the load fails loud, rather than permanently removing a uniqueness
       * guarantee (possibly a user-defined one) on the strength of one batch. Mirrors `deleteColumns`.
       */
      dropUniqueConstraints?: boolean;

      autoSplit?: boolean;

      addTimestamps?: boolean;
      /**
       * Load via a staging temp table (default `true`): empty clone, populate, merge, drop. Gives an
       * atomic all-or-nothing merge, is the target for `bulkLoad`, and runs conflict resolution.
       *
       * `false` loads straight to the target, skipping the temp-table round-trips. Upsert still
       * works. Required `true` for `addHistory`, which diffs the staging table against the target.
       */
      useStagingInsert?: boolean;
      addHistory?: boolean;
      historyTables?: string[];
      addNested?: boolean;
      nestedTables?: string[];
      excludeBlankColumns?: boolean;

      /**
       * Strip unstorable characters (NUL bytes, unpaired UTF-16 surrogates) before insert. These
       * hard-fail Postgres and can corrupt MySQL, and connection-charset pinning does not address
       * them. Off by default because it mutates data.
       */
      sanitizeInvalidChars?: boolean;

      useWorkers?: boolean;
      maxWorkers?: number;

      /**
       * Per-worker-task timeout in SECONDS, `0` (default) disables. A worker that DIES is already
       * caught by the pool's exit/error handlers; this only guards an alive-but-wedged worker. Off by
       * default so a legitimately long batch is not spuriously failed.
       */
      workerTaskTimeout?: number;

      /**
       * Column names always stored as varchar, for string-encoded identifiers (phone numbers, zip
       * codes, padded codes) that would otherwise infer as numeric.
       */
      forceStringColumns?: string[];

      /**
       * Column names always stored as a boolean flag. autosql infers boolean only from
       * `true`/`false`, since a bare `0`/`1` is more often an integer. Values outside the boolean
       * domain are rejected rather than coerced, because forcing to boolean is lossy.
       */
      booleanColumns?: string[];

      /**
       * Explicit number-format separators. Set BOTH to disambiguate single-separator values: e.g.
       * thousands `"."` with decimal `","` parses "1.000" as 1000. Omit both for auto-detection.
       */
      thousandsSeparator?: string;
      decimalSeparator?: string;

      /**
       * Regional preset, sugar over `thousandsSeparator`/`decimalSeparator` and resolved to them in
       * `validateConfig` so it reaches both inference and storage.
       *
       *  - `"US"` / `"IN"`: thousands `","`, decimal `"."` (Indian grouping accepted automatically).
       *  - `"EU"`: thousands `"."`, decimal `","`.
       *
       * Explicit separators win when both are supplied.
       */
      numberFormat?: "US" | "EU" | "IN";

      /**
       * With no explicit separators or `numberFormat`, the layout is inferred from structural
       * evidence in the data, one layout for the whole load. A value that can only be one layout is a
       * vote; the ambiguous `"1,234"` shape abstains. Contradictory evidence falls back to decimal
       * plus a warning.
       *
       * This is how many votes a layout needs before it is trusted. Default 1: one structural value
       * is certainty, not a guess. Raise it to tolerate stray values.
       */
      numberFormatMinEvidence?: number;

      /**
       * IANA time zone that ZONELESS datetime inputs are interpreted as, then converted to a UTC
       * instant for storage. Inputs already carrying a zone are untouched, and `date`/`time` columns
       * are never shifted. Omit to store zoneless values as given. autosql NEVER infers this from
       * the host process timezone. It normalises the stored instant; it does not by itself make a
       * column round-trip a source offset.
       */
      sourceTimeZone?: string;

      /**
       * Acquire a per-table advisory lock before schema inference and ALTER TABLE. Default `false`;
       * set `true` when concurrent processes may write the same table, to prevent compareMetaData races.
       */
      useSchemaLock?: boolean;
      /** Seconds to wait for the advisory lock before throwing `SchemaLockTimeoutError`. Default 30. */
      schemaLockTimeout?: number;

      // --- Schema history ---
      /** Record every DDL event to an audit table. Default: false. */
      schemaHistory?: boolean;
      /** Name of the history table. Default: "autosql_schema_history". */
      schemaHistoryTable?: string;
      /** Schema containing the history table (same DB, different schema). Default: same as config.schema. */
      schemaHistorySchema?: string;
      /** Throw SchemaDriftError when drift is detected. Default: false (warn only). */
      strictDriftDetection?: boolean;
      /** Run drift detection on every autoSQL call when schemaHistory: true. Default: true. */
      detectDrift?: boolean;

      // --- Run audit ---
      /** Persist one row per top-level load (autoSQL/autoSQLChunked/stream end) to a managed run-audit
       *  table — run counts, durations, row counts, success/error — with no caller wiring. Best-effort:
       *  a failed audit write never fails the load. Default: false. */
      runAudit?: boolean;
      /** Name of the run-audit table. Default: "autosql_runs". */
      runAuditTable?: string;
      /** Schema containing the run-audit table. Default: same as config.schema. */
      runAuditSchema?: string;

      // --- Streaming ---
      /** Prefix for per-run stream staging tables. Default: "autosql_stream__". */
      streamingStagingPrefix?: string;
      /**
       * Max per-row widening retry rounds after a bulk insert/merge fails. Default: 3. Applies to the
       * streaming flush AND the non-streaming direct-insert path (`useStagingInsert: false`).
       */
      streamMaxRetries?: number;
      /**
       * Opt-in rejected-rows table. Rows still failing after per-row retries are written here instead
       * of throwing. Applies to the streaming flush and the direct-insert path; no effect on the
       * default staging path, which stays all-or-nothing by design.
       */
      rejectedRowsTable?: string;
      /** Schema for the rejected rows table. Default: same as config.schema. */
      rejectedRowsSchema?: string;
      /** When true, orphaned stream staging tables are preserved instead of dropped. Default: false. */
      keepOrphanedStagingTables?: boolean;

      /**
       * Prefix for auto-created staging tables (default: "temp_staging__").
       * Change this if your schema already has tables with that prefix.
       */
      stagingPrefix?: string;
      /**
       * Suffix for auto-created history tables (default: "__history").
       * Change this if your schema already has tables with that suffix.
       */
      historyTableSuffix?: string;

      /**
       * Optional logger. When omitted, the library writes nothing to stdout/stderr.
       * Pass `console` to restore the old behaviour, or supply your own structured logger.
       */
      logger?: {
          log?: (msg: string) => void;
          warn?: (msg: string) => void;
          error?: (msg: string) => void;
          /**
           * Structured per-run metrics sink (see `QueryStats`). Called once per `autoSQL` load with
           * phase timings + throughput, so a pipeline can forward them to observability without parsing
           * log strings. Optional; omit to not collect metrics.
           */
          stats?: (stats: QueryStats) => void;
      };

      /**
       * TLS for the driver connection. Omit **or `false`** (default) → no change: plaintext / driver
       * default (existing configs byte-for-byte unaffected). `true` → TLS with default verification. An
       * object configures TLS:
       *   - `ca`: PEM CA bundle to verify the server cert against (e.g. AWS RDS bundle, or a BYOD CA).
       *   - `rejectUnauthorized`: verify the cert chain. Defaults to driver default (true) when a `ca`
       *     is supplied; set `false` ONLY for dev/self-signed (verification then off).
       *   - `cert` / `key`: client certificate + key for mutual TLS (optional).
       *   - `servername`: SNI override when the host differs from the cert CN/SAN.
       * Works on **all three dialects**: MySQL/Postgres get it as the driver `ssl` object; SQL Server
       * maps it onto mssql's `encrypt` / `trustServerCertificate` / `cryptoCredentialsDetails`
       * automatically. Not composed with `sshConfig` — pick one path (SSH tunnel OR direct TLS).
       */
      ssl?: boolean | {
        ca?: string;
        cert?: string;
        key?: string;
        rejectUnauthorized?: boolean;
        servername?: string;
      };

      sshConfig?: SSHKeys;
      sshStream?: ClientChannel | null;
      sshClient?: SSHClient;
}

export interface SSHKeys {
  host: string;
  port: number;
  username: string;
  password?: string;
  private_key_path?: string;
  private_key?: string;
  /**
   * Expected OpenSSH host-key fingerprint, e.g. "SHA256:abc123…" (get it with `ssh-keyscan -t
   * ed25519 <host> | ssh-keygen -lf -`). When set, the tunnel VERIFIES the bastion's host key and
   * refuses a mismatch, closing the MITM window that ssh2 leaves open by doing no verification at
   * all. Omitted: still connects, with a loud warning that identity is unverified.
   */
  hostFingerprint?: string;
  timeout?: number;
  debug?: boolean;
  source_address?: string;
  source_port?: number;
  destination_address: string;
  destination_port: number;
}

export type QueryInput = string | QueryWithParams;
export type QueryWithParams = { query: string; params?: any[] };

export interface TranslateMap {
    serverToLocal: Record<string, string>;
    localToServer: Record<string, string>;
  }
  
export interface DialectConfig {
    dialect: supportedDialects;
    requireLength: string[];
    optionalLength: string[];
    noLength: string[];
    decimals: string[];
    translate: TranslateMap;
    defaultTranslation: Record<string, string>;
    sqlize: SqlizeRule[]
    engine: string;
    charset: string;
    collate: string;
    encoding: string;
    maxIndexCount?: number;
    /** Max fractional-digit scale the dialect's decimal type holds (MySQL 30, SQL Server 38, Postgres
     *  16383). Default decimal scale ceiling — stored at full precision up to the DB limit, not an
     *  arbitrary low cap. */
    maxDecimalScale: number;
}

export interface InsertResult { 
  start: Date; 
  end: Date; 
  duration: number; 
  affectedRows: number 
}

export interface InsertInput {
  table: string,
  data: Record<string, any>[],
  metaData: MetadataHeader,
  previousMetaData: AlterTableChanges | MetadataHeader | null,
  comparedMetaData?: { changes: AlterTableChanges, updatedMetaData: MetadataHeader },
  runQuery?: boolean,
  insertType?: "UPDATE" | "INSERT",
  stagingPrefix?: string,
  historyTableSuffix?: string
}

export interface QueryResult {
    start: Date; 
    end: Date; 
    duration: number;
    affectedRows?: number 
    success: boolean;
    results?: any[];
    error?: string;
    /**
     * The driver's structured error code (mysql2 `code`, Postgres SQLSTATE, SQL Server error
     * number), so a caller can branch on the exact failure without string-matching `error`. Omitted
     * for non-driver errors.
     */
    errorCode?: string;
    table?: string;
    /**
     * The resolved schema autosql used, including managed columns (`dwh_*` timestamps, surrogate).
     * Cache and pass back as `existingSchema` to skip re-introspection on the next load.
     */
    metaData?: MetadataHeader;
    /** Per-run performance metrics (phase timings + throughput). Populated on a successful `autoSQL`
     *  load; the same object is passed to `logger.stats`. See `QueryStats`. */
    stats?: QueryStats;
}

/**
 * Per-run performance metrics for one `autoSQL` load. Durations are wall-clock milliseconds per phase.
 */
export interface QueryStats {
    table: string;
    /** Number of input rows passed to `autoSQL`. */
    rows: number;
    /** Rows the database reported affected by the load (insert + update). */
    affectedRows: number;
    /** Total wall-clock time for the whole `autoSQL` call. */
    durationMs: number;
    /** `rows / (durationMs / 1000)` — input-row throughput. */
    rowsPerSecond: number;
    phases: {
        /** Input prep + schema inference/resolution (`predictType`/introspection/compare). */
        prepare?: number;
        /** DDL: CREATE / ALTER to make the table match the resolved schema. */
        configure?: number;
        /** Data load: staging populate + merge into the target, or a direct insert. */
        load?: number;
    };
    /** Whether the staging-table path was used (vs a direct insert). */
    staged: boolean;
    /** Whether the bulk-copy path (`COPY` / `LOAD DATA`) was used to populate. */
    bulkLoad: boolean;
}

export interface metaDataInterim {
  [key: string]: {
    uniqueSet: Set<any>;
    uniqueSaturated: boolean;
    valueCount: number;
    nullCount: number;
    types: Set<string>;
    collated_type?: string;
    length: number;
    byteLength: number;
    decimal: number;
    trueMaxDecimal: number;
    // Running max of integer-part digits. Precision = maxIntegerDigits + maxScale; tracking the
    // integer part separately avoids under-counting when the widest-integer and widest-scale values
    // are different rows.
    intLen?: number;
  }
}

export interface SqlizeRule {
  regex: string;
  replace: string;
  type: true | string[]; // `true` = apply to all types
}

import type { Database } from "./database";
import type { AutoSQLHandler } from "./autosql";
import type { MetadataHeader, QueryResult, QueryStats } from "../config/types";
import { getMetaData, compareMetaData, restrictInferredUniques } from "../helpers/metadata";
import { writeRunAudit } from "../helpers/runAudit";
import { tableChangesExist } from "../helpers/utilities";
import { DEFAULTS } from "../config/defaults";
import {
    buildCreateStreamStagingTableQuery,
    buildInsertIntoStreamStagingQuery,
    buildSelectFromStreamStagingQuery,
    buildDropStreamStagingTableQuery,
    buildMergeFromStreamQuery,
    buildAddStreamStagingColumnsQuery,
    buildStagingStateQuery,
    isStagingMetaColumn,
    STAGING_COLUMN_PREFIX,
    STAGING_SEQ_COLUMN,
} from '../helpers/streamHelpers';

/**
 * Collapse rows sharing a primary key to the one staged last, ordered by `_autosql_seq`.
 * JSON-encodes the key tuple so a composite key can't be made ambiguous by a separator (A24).
 */
function dedupByKeyKeepingLast(rows: Record<string, any>[], primaryKey: string[]): Record<string, any>[] {
    const bySeq = new Map<string, Record<string, any>>();
    for (const row of rows) {
        const key = JSON.stringify(primaryKey.map(k => row[k] ?? null));
        const held = bySeq.get(key);
        if (!held || Number(row[STAGING_SEQ_COLUMN] ?? 0) >= Number(held[STAGING_SEQ_COLUMN] ?? 0)) {
            bySeq.set(key, row);
        }
    }
    return [...bySeq.values()];
}

export class AutoSQLStreamHandle {
    private handler: AutoSQLHandler;
    private db: Database;
    private table: string;
    private stagingTable: string;
    private schema: string | undefined;
    private primaryKey: string[] | undefined;
    private columns: string[] | null = null;
    private columnSet: Set<string> | null = null;
    private stagingCreated = false;
    private ended = false;
    /** Opened with a `sessionKey`, so staging may outlive this run. */
    public readonly resumable: boolean;
    /**
     * Attached to rows an earlier run staged.
     *
     * ⚠ A caller with its own resume point must read this: trusting a stored high-water mark against
     * a non-adopted stream silently drops every row before that mark.
     */
    public readonly adopted: boolean;
    /** Columns added to an adopted table mid-load. Reporting only; the load is correct either way. */
    public readonly widenedColumns: string[] = [];
    /** Cursors this handle staged, for reporting. `stagingState()` reads the table for the truth. */
    private cursorsWritten = new Set<string>();

    constructor(
        handler: AutoSQLHandler,
        db: Database,
        table: string,
        stagingTable: string,
        schema: string | undefined,
        primaryKey: string[] | undefined,
        resume?: { resumable: boolean; adoptedColumns: string[] | null }
    ) {
        this.handler = handler;
        this.db = db;
        this.table = table;
        this.stagingTable = stagingTable;
        this.schema = schema;
        this.primaryKey = primaryKey;
        this.resumable = resume?.resumable ?? false;

        // Pre-set so write() doesn't try to create a table that's already there.
        const adoptedColumns = resume?.adoptedColumns ?? null;
        if (adoptedColumns && adoptedColumns.length > 0) {
            this.columns = adoptedColumns;
            this.columnSet = new Set(adoptedColumns);
            this.stagingCreated = true;
            this.adopted = true;
        } else {
            this.adopted = false;
        }
    }

    /**
     * Append a chunk of rows to this run's staging table.
     *
     * Rejects on failure and MUST be awaited: an un-awaited failing write() becomes an unhandled
     * rejection and its error is lost. A rejected write() leaves staging indeterminate, so either
     * retry the same chunk (write() is append-only, so re-sending is safe) or {@link abort}. Do NOT
     * call {@link end} expecting the gap to be ignored; end() merges whatever is staged, so a lost
     * chunk becomes missing rows.
     */
    async write(chunk: Record<string, any>[], opts?: { cursor?: string }): Promise<void> {
        if (this.ended) throw new Error(`autoSQLStream: write() called after end()/abort()`);
        if (chunk.length === 0) return;
        const cursor = opts?.cursor;
        if (cursor !== undefined) {
            if (!this.resumable) {
                throw new Error(`autoSQLStream: a cursor is only meaningful on a stream opened with a sessionKey — a per-run staging table is dropped at the end of the run, so nothing could read the cursor back.`);
            }
            if (!this.primaryKey?.length) {
                throw new Error(`autoSQLStream: a cursor requires a primaryKey — resuming re-sends the page that failed, and without a key those duplicate rows cannot be deduplicated at merge.`);
            }
            this.cursorsWritten.add(cursor);
        }
        return this.db.runWithSchema(this.schema, async () => {
            const config = this.db.getConfig();

            if (!this.stagingCreated) {
                // Columns from the UNION of the first chunk's rows — not just chunk[0], which would
                // silently drop a key first appearing in a later row of the same chunk (A18).
                const cols = new Set<string>();
                for (const row of chunk) for (const k of Object.keys(row)) cols.add(k);
                // Reserved, or the injected column collides and the CREATE fails unhelpfully.
                const reserved = [...cols].filter(isStagingMetaColumn);
                if (reserved.length > 0) {
                    throw new Error(`autoSQLStream: column(s) ${reserved.join(', ')} use the reserved '${STAGING_COLUMN_PREFIX}' prefix, which autosql uses for its own staging columns. Rename them.`);
                }
                this.columns = [...cols];
                this.columnSet = cols;
                const createQ = buildCreateStreamStagingTableQuery(this.stagingTable, this.columns, config);
                const createResult = await this.db.runTransaction([createQ]);
                if (!createResult.success) {
                    throw new Error(`autoSQLStream: failed to create stream staging table '${this.stagingTable}': ${createResult.error}`);
                }
                this.stagingCreated = true;
            }

            // A key first appearing in a LATER row/chunk has no column to land in, and dropping it
            // silently is data loss (A18).
            const unknown: string[] = [];
            for (const row of chunk) {
                for (const k of Object.keys(row)) {
                    if (!this.columnSet!.has(k) && !unknown.includes(k)) unknown.push(k);
                }
            }
            if (unknown.length > 0) {
                // Widen rather than refuse: absorbing a drifted source is what autosql does
                // everywhere else, and refusing would strand a resume mid-load. `safeMode` means no
                // DDL, so there the only non-lossy option left is to refuse. A keyless stream keeps
                // the established throw — its columns came from its own first chunk moments earlier,
                // so an unknown key is caller inconsistency, not drift between runs.
                if (this.resumable && !config.safeMode) {
                    const alterQ = buildAddStreamStagingColumnsQuery(this.stagingTable, unknown, config);
                    const alterResult = await this.db.runTransaction([alterQ]);
                    if (!alterResult.success) {
                        throw new Error(`autoSQLStream: failed to widen staging table '${this.stagingTable}' with new column(s) ${unknown.join(', ')}: ${alterResult.error}`);
                    }
                    for (const k of unknown) { this.columns!.push(k); this.columnSet!.add(k); }
                    this.widenedColumns.push(...unknown);
                    this.db.warn(`autoSQLStream: staging table '${this.stagingTable}' widened with new column(s) ${unknown.join(', ')} that appeared after it was created.`);
                } else {
                    const why = this.resumable
                        ? `safeMode is set, so the staging table cannot be altered to fit it`
                        : `a stream requires a stable column set`;
                    throw new Error(`autoSQLStream: row has column '${unknown[0]}' that was not present when the stream started (columns: ${this.columns!.filter(c => !unknown.includes(c)).join(', ')}). ${why} — include '${unknown[0]}' in the first written rows, or use a separate stream/load for it.`);
                }
            }

            // SQL Server caps a request at 2,100 bound parameters, so split the chunk into sub-batches of
            // ≤ floor(2000 / colCount) rows (one request each). Other dialects send the whole chunk in one.
            // A bound cursor is one more parameter per row, so it counts toward the cap.
            const boundPerRow = this.columns!.length + (cursor !== undefined ? 1 : 0);
            const perStatement = config.sqlDialect === 'sqlserver'
                ? Math.max(1, Math.floor(2000 / boundPerRow))
                : chunk.length;
            for (let i = 0; i < chunk.length; i += perStatement) {
                const sub = chunk.slice(i, i + perStatement);
                const insertQ = buildInsertIntoStreamStagingQuery(this.stagingTable, this.columns!, sub, config, cursor);
                const insertResult = await this.db.runTransaction([insertQ]);
                if (!insertResult.success) {
                    throw new Error(`autoSQLStream: failed to write chunk to staging table '${this.stagingTable}': ${insertResult.error}`);
                }
            }
        });
    }

    /**
     * Merge all staged rows into the target (infer schema, apply DDL, bulk INSERT…SELECT with a
     * per-row retry fallback), then drop staging.
     *
     * Rejects on failure and must be awaited. end() merges whatever is staged and knows nothing of
     * write() calls that failed or were never awaited, so a lost chunk silently becomes missing rows.
     */
    async end(): Promise<QueryResult> {
      return this.db.runWithSchema(this.schema, async () => {
        const start = new Date();
        this.ended = true;
        const config = this.db.getConfig();
        const insertType = config.insertType ?? 'UPDATE';
        const maxRetries = config.streamMaxRetries ?? DEFAULTS.streamMaxRetries;
        // Per-run instrumentation (QueryStats). For a stream these cover the `end()` FLUSH — read
        // staging + infer (prepare) → DDL (configure) → merge (load) — not the incremental write()s.
        const perf = () => (typeof performance !== "undefined" ? performance.now() : Date.now());
        const phases: { prepare?: number; configure?: number; load?: number } = {};
        let promoted = false; // gates the drop in `finally`

        try {
            if (!this.stagingCreated) {
                // Nothing was written
                return { start, end: new Date(), success: true, duration: 0, affectedRows: 0, table: this.table };
            }

            const selectQ = buildSelectFromStreamStagingQuery(this.stagingTable, config);
            const selectResult = await this.db.runQuery(selectQ);
            if (!selectResult.success || !selectResult.results) {
                throw new Error(`autoSQLStream: failed to read staging data: ${selectResult.error}`);
            }
            // Dedup BEFORE inference, not just at merge. A resumed run re-sends the page it died on,
            // so a key legitimately appears twice in staging — and inference reading that decides the
            // key is not unique and WIDENS it (an `id` re-send produced a composite `(id, name)` PK).
            // Keep the last-staged row per key, matching the merge's own dedup.
            const rawRows: Record<string, any>[] = this.resumable && this.primaryKey?.length
                ? dedupByKeyKeepingLast(selectResult.results, this.primaryKey)
                : selectResult.results;
            // Strip after: `_autosql_*` describes the load, not the data.
            const stagingRows: Record<string, any>[] = rawRows.map((r: Record<string, any>) => {
                const out: Record<string, any> = {};
                for (const k of Object.keys(r)) if (!isStagingMetaColumn(k)) out[k] = r[k];
                return out;
            });
            if (stagingRows.length === 0) {
                // Nothing to lose by dropping an empty table, so don't leak it to the sweeper.
                promoted = true;
                return { start, end: new Date(), success: true, duration: 0, affectedRows: 0, table: this.table };
            }

            // Overlay the resolved separators on inference AND the per-row fallback: the bulk merge
            // casts via the DB, so a grouped value like "1,234" is rejected there and lands per-row,
            // where sqlize normalizes under these separators. numberFormat needs no overlay, being
            // already on this.config.
            const separators = this.handler['resolveSeparatorConsensus'](stagingRows);
            const flushConfig = separators
                ? { ...config, thousandsSeparator: separators.thousands, decimalSeparator: separators.decimal }
                : config;

            const tPrepare = perf();
            const { currentMetaData } = await this.handler.fetchTableMetadata(this.table);
            const inferredMeta = restrictInferredUniques(await getMetaData(flushConfig, stagingRows, this.primaryKey), currentMetaData, config);
            const { changes, updatedMetaData } = compareMetaData(currentMetaData, inferredMeta, this.db.getDialectConfig(), config.logger);
            phases.prepare = perf() - tPrepare;

            const insertInput = [{
                table: this.table,
                data: stagingRows,
                metaData: updatedMetaData,
                previousMetaData: currentMetaData,
                comparedMetaData: { changes, updatedMetaData },
                stagingPrefix: config.stagingPrefix,
                historyTableSuffix: config.historyTableSuffix,
            }];

            const useSchemaLock = config.useSchemaLock;
            const lockTimeout = config.schemaLockTimeout ?? DEFAULTS.schemaLockTimeout;
            const useHistory = config.schemaHistory;
            let historyId: number | undefined;

            if (useSchemaLock) await this.db.acquireSchemaLock(this.table, lockTimeout);
            try {
                if (useHistory) {
                    await this.handler['history'].bootstrap();
                    if (tableChangesExist(changes)) {
                        historyId = await this.handler['history'].recordStart(this.table, currentMetaData || {}, changes);
                    }
                }
                try {
                    const tConfigure = perf();
                    await this.handler['configureTables'](insertInput);
                    phases.configure = perf() - tConfigure;
                    if (historyId !== undefined) await this.handler['history'].recordSuccess(historyId, updatedMetaData);
                } catch (ddlErr) {
                    if (historyId !== undefined) await this.handler['history'].recordFailed(historyId).catch(() => {});
                    throw ddlErr;
                }
            } finally {
                if (useSchemaLock) await this.db.releaseSchemaLock(this.table);
            }

            const tLoad = perf();
            // Any resumable stream, not just cursored ones: a resume can re-send staged rows.
            const mergeQ = buildMergeFromStreamQuery(this.table, this.stagingTable, updatedMetaData, insertType, config, this.resumable);
            const mergeResult = await this.db.runTransaction([mergeQ]);

            let affectedRows = mergeResult.affectedRows ?? 0;

            if (!mergeResult.success) {
                // Fallback: per-row retry with schema widening, under the resolved separators so the
                // per-row sqlize (via getConfig()) normalizes values with the detected format.
                affectedRows = await this.db.runWithSeparators(separators, () =>
                    this._perRowMerge(stagingRows, updatedMetaData, insertType, maxRetries));
            }
            phases.load = perf() - tLoad;

            const end = new Date();
            const durationMs = end.getTime() - start.getTime();
            const stats: QueryStats = {
                table: this.table,
                rows: stagingRows.length,
                affectedRows,
                durationMs,
                rowsPerSecond: durationMs > 0 ? Math.round((stagingRows.length / durationMs) * 1000) : 0,
                phases: {
                    prepare: phases.prepare !== undefined ? Math.round(phases.prepare) : undefined,
                    configure: phases.configure !== undefined ? Math.round(phases.configure) : undefined,
                    load: phases.load !== undefined ? Math.round(phases.load) : undefined,
                },
                staged: true,
                bulkLoad: !!config.bulkLoad,
            };
            try { config.logger?.stats?.(stats); } catch { /* a metrics sink must never break a load */ }
            await writeRunAudit(this.db, { table: this.table, success: true, rows: stagingRows.length, affectedRows, durationMs, rowsPerSecond: stats.rowsPerSecond, phases: stats.phases, staged: true, bulkLoad: !!config.bulkLoad });
            promoted = true;
            return { start, end, success: true, duration: durationMs, affectedRows, table: this.table, stats };
        } catch (error: any) {
            const end = new Date();
            const durationMs = end.getTime() - start.getTime();
            // rows/affected unknown here (the failure may precede the staging read) — record 0 with the error.
            await writeRunAudit(this.db, { table: this.table, success: false, rows: 0, affectedRows: 0, durationMs, rowsPerSecond: 0, staged: true, bulkLoad: !!this.db.getConfig().bulkLoad, error: error instanceof Error ? error.message : String(error), errorCode: error?.code != null ? String(error.code) : undefined });
            return { start, end, duration: durationMs, affectedRows: 0, success: false, error: error instanceof Error ? error.message : String(error), errorCode: error?.code != null ? String(error.code) : undefined };
        } finally {
            // A resumable stream keeps its table when the rows didn't land: the failure may be
            // transient, and dropping here would discard rows accumulated over earlier runs, the
            // exact loss this feature exists to prevent. Per-run tables are useless after the call.
            const keepForResume = this.resumable && !promoted;
            if (this.stagingCreated && !keepForResume) {
                const dropQ = buildDropStreamStagingTableQuery(this.stagingTable, this.db.getConfig());
                await this.db.runTransaction([dropQ]).catch(e =>
                    this.db.error(`autoSQLStream: failed to drop staging table '${this.stagingTable}': ${e.message}`)
                );
            } else if (keepForResume) {
                this.db.warn(`autoSQLStream: end() did not promote staged rows for '${this.table}'; keeping resumable staging table '${this.stagingTable}' so the run can be retried. Call abort() to discard it.`);
            }
            this.handler.releaseStreamStaging(this.stagingTable);
        }
      });
    }

    private async _perRowMerge(
        rows: Record<string, any>[],
        metaData: MetadataHeader,
        insertType: 'UPDATE' | 'INSERT',
        maxRetries: number
    ): Promise<number> {
        // Shared with the non-streaming direct-insert path — see AutoSQLHandler.perRowInsertWithRetry.
        const { inserted } = await this.handler.perRowInsertWithRetry(
            this.table, rows, metaData, insertType, maxRetries, this.primaryKey, 'autoSQLStream'
        );
        return inserted;
    }

    /**
     * What is currently staged, for a caller that lost its run. Reads the table, not this handle, so
     * it is valid when another process staged the rows. See README.
     */
    async stagingState(): Promise<{
        stagedRows: number;
        cursors: string[];
        lastCursor: string | null;
        firstStagedAt: Date | null;
        lastStagedAt: Date | null;
    }> {
        const empty = { stagedRows: 0, cursors: [], lastCursor: null, firstStagedAt: null, lastStagedAt: null };
        if (!this.stagingCreated) return empty;
        return this.db.runWithSchema(this.schema, async () => {
            const result = await this.db.runQuery(buildStagingStateQuery(this.stagingTable, this.db.getConfig()));
            if (!result.success || !result.results?.length) return empty;
            const pick = (r: any, k: string) => r[k] ?? r[k.toUpperCase()];
            const rows = result.results;
            let stagedRows = 0;
            const cursors: string[] = [];
            const stamps: Date[] = [];
            for (const r of rows) {
                stagedRows += Number(pick(r, 'row_count')) || 0;
                const c = pick(r, 'cursor_value');
                if (c !== null && c !== undefined) cursors.push(String(c));
                for (const k of ['first_staged_at', 'last_staged_at']) {
                    const v = pick(r, k);
                    if (v) stamps.push(v instanceof Date ? v : new Date(v));
                }
            }
            stamps.sort((a, b) => a.getTime() - b.getTime());
            return {
                stagedRows,
                cursors,
                lastCursor: cursors.length ? cursors[cursors.length - 1] : null,
                firstStagedAt: stamps.length ? stamps[0] : null,
                lastStagedAt: stamps.length ? stamps[stamps.length - 1] : null,
            };
        });
    }

    /**
     * Stop without promoting and without discarding, so a later run can adopt the staging table.
     *
     * Throws on a non-resumable stream: its table name is per-invocation, so suspending would leak a
     * table nothing can ever find again, and both that and silently dropping the rows are worse than
     * a loud refusal.
     */
    async suspend(): Promise<void> {
        if (!this.resumable) {
            throw new Error(
                `autoSQLStream: suspend() requires a stream opened with a sessionKey — a per-run staging table cannot be resumed, ` +
                `so suspending it would leave an unreachable table behind. Use end() to merge or abort() to discard.`
            );
        }
        this.ended = true;
        this.handler.releaseStreamStaging(this.stagingTable);
    }

    /**
     * Discard the run: drop the staging table without merging. Safe to call even if {@link write}
     * was never called, and the correct way to bail out after a failed write(). On a resumable
     * stream this discards work accumulated across earlier runs too — use {@link suspend} to keep it.
     * Returns a promise that should be awaited.
     */
    async abort(): Promise<void> {
        this.ended = true;
        return this.db.runWithSchema(this.schema, async () => {
            if (this.stagingCreated) {
                const dropQ = buildDropStreamStagingTableQuery(this.stagingTable, this.db.getConfig());
                await this.db.runTransaction([dropQ]).catch(e =>
                    this.db.error(`autoSQLStream: failed to drop staging table during abort: ${e.message}`)
                );
            }
            this.handler.releaseStreamStaging(this.stagingTable);
        });
    }
}

import type { MySQLDatabase } from "./mysql";
import type { PostgresDatabase } from "./pgsql";
import type { SqlServerDatabase } from "./sqlserver";
import type { Database } from "./database";
import type { InsertInput, MetadataHeader, AlterTableChanges, QueryResult, QueryInput, AutoSQLOptions, OpenStreamOptions, QueryStats, AutoSQLPreview, TablePreview, DatabaseConfig } from "../config/types";
import { getMetaData, compareMetaData, collectDataColumns, schemaCoversColumns, overlaySchema, fillColumnDefaults, restrictInferredUniques } from "../helpers/metadata";
import { applySurrogateKey } from "../helpers/keys";
import { resolveDatasetSeparators } from "../helpers/numberFormat";
import { writeRunAudit } from "../helpers/runAudit";
import { HistoryCoordinator } from "./historyCoordinator";
import { DegradationPolicy } from "./degradationPolicy";
import { StagingPipeline } from "./stagingPipeline";
import { RowStoreLoadStrategy } from "./loadStrategy";
import { parseDatabaseMetaData, tableChangesExist, isMetadataHeader, estimateRowSize, isValidDataFormat, organizeSplitTable, organizeSplitData, splitInsertData, getInsertValues, throwIfFailedResults } from "../helpers/utilities";
import { DEFAULTS, MAX_COLUMN_COUNT } from "../config/defaults";
import { ensureTimestamps } from "../helpers/timestamps";
import WorkerHelper from "../workers/workerHelper";
import { buildCompensatingDDL } from "../helpers/compensatingDDL";
import {
    generateRunId,
    buildStreamStagingTableName,
    buildResumableStagingTableName,
    isAutosqlStreamTable,
    isResumableStreamTable,
    buildStagingColumnsQuery,
    isStagingMetaColumn,
    buildDropStreamStagingTableQuery,
} from '../helpers/streamHelpers';
import { AutoSQLStreamHandle } from "./autoSQLStreamHandle";
export { AutoSQLStreamHandle };

export class AutoSQLHandler {
    private db: Database;
    private history: HistoryCoordinator;
    private degradation: DegradationPolicy;
    private staging: StagingPipeline;
    private strategy: RowStoreLoadStrategy;
    // Staging tables of streams open on this instance. Orphan cleanup must never drop these: a
    // concurrent stream to the same table shares the `${prefix}${table}__` pattern.
    private activeStreamStagingTables = new Set<string>();

    constructor(dbInstance: MySQLDatabase | PostgresDatabase | SqlServerDatabase) {
        this.db = dbInstance;
        this.history = new HistoryCoordinator(this, dbInstance);
        this.degradation = new DegradationPolicy(this, dbInstance);
        this.staging = new StagingPipeline(this, dbInstance);
        this.strategy = new RowStoreLoadStrategy(this, dbInstance, this.staging, this.history);
    }

    /** Delegator so AutoSQLStreamHandle reaches the shared per-row degradation engine. */
    async perRowInsertWithRetry(
        table: string,
        rows: Record<string, any>[],
        metaData: MetadataHeader,
        insertType: 'UPDATE' | 'INSERT',
        maxRetries: number,
        primaryKey?: string[],
        label: string = 'autoSQL'
    ): Promise<{ inserted: number; rejected: Record<string, any>[] }> {
        return this.degradation.perRowInsertWithRetry(table, rows, metaData, insertType, maxRetries, primaryKey, label);
    }

    releaseStreamStaging(stagingTable: string): void {
        this.activeStreamStagingTables.delete(stagingTable);
    }

    /**
     * Infer ONE dataset-level {thousands, decimal} pair from structural evidence pooled across all
     * columns, so a decisive column resolves ambiguous siblings. Reads only `data`. Meant to run
     * under `db.runWithSeparators(...)`, which overlays it for inference, load-time sqlize and
     * worker dispatch.
     *
     * Returns undefined (load keeps the assume-decimal default plus the A24c per-column warning)
     * when separators are already configured, or evidence is absent or contradictory.
     */
    private resolveSeparatorConsensus(data: Record<string, any>[]): { thousands: string; decimal: string } | undefined {
        const config = this.db.getConfig();
        // Explicit separators / numberFormat (both resolve to thousandsSeparator in validateConfig) win.
        if (config.thousandsSeparator !== undefined || config.decimalSeparator !== undefined) return undefined;
        if (!Array.isArray(data) || data.length === 0) return undefined;

        const decision = resolveDatasetSeparators(data, config.numberFormatMinEvidence ?? 1);
        if (decision === null) return undefined; // no evidence → default; A24c warns per ambiguous column
        if ("conflict" in decision) {
            this.db.warn(`autosql: the data contains conflicting number formats (some values look US "1,234,567", others EU "1.234.567"). Not guessing — using the default (a lone separator is treated as a decimal). Set numberFormat or thousandsSeparator/decimalSeparator to disambiguate.`);
            return undefined;
        }
        this.db.log(`autosql: detected ${decision.thousands === "," ? "US/IN" : "EU"} number format from the data (thousands "${decision.thousands}", decimal "${decision.decimal}").`);
        return decision;
    }

    /**
     * Dry run: what an `autoSQL` load WOULD do, without writing anything. Only the current schema is
     * read, to diff against. Contrast with `safeMode`, which runs the load but skips DDL.
     */
    async preview(table: string, data: Record<string, any>[], schema?: string, primaryKey?: string[], options?: AutoSQLOptions): Promise<AutoSQLPreview> {
        const separators = this.resolveSeparatorConsensus(data);
        return this.db.runWithSeparators(separators, () => this.db.runWithSchema(schema, async () => {
            const insertInput = await this.prepareInsertData(table, data, schema, primaryKey, options);
            const config = this.db.getConfig();
            const numberFormat = (config.thousandsSeparator !== undefined && config.decimalSeparator !== undefined)
                ? { thousands: config.thousandsSeparator, decimal: config.decimalSeparator }
                : undefined;

            // TODO: also surface the per-column A24c ambiguity warning here. It is emitted to
            // logger.warn during inference, so capturing it needs a log-capture seam (an ALS channel
            // like schemaContext), deferred to keep v1 free of that infra.
            const tables: TablePreview[] = [];
            for (const input of insertInput) {
                const { currentMetaData, tableExists } = await this.fetchTableMetadata(input.table);
                const changes = input.comparedMetaData?.changes ?? null;
                const hasChanges = changes ? tableChangesExist(changes) : false;
                const action: TablePreview["action"] = !tableExists ? "create" : (hasChanges ? "alter" : "noop");

                // Same call configureTables makes per table, but runQuery:false so it BUILDS the
                // CREATE/ALTER without executing — read-only.
                let ddl: string[] = [];
                try {
                    const ddlResult = await this.autoConfigureTable({ ...input, runQuery: false }) as QueryInput[];
                    if (Array.isArray(ddlResult)) ddl = ddlResult.map(q => typeof q === "string" ? q : q.query);
                } catch { /* a noop table may produce no DDL; leave ddl empty */ }

                tables.push({
                    table: input.table,
                    action,
                    inferredSchema: input.metaData,
                    currentSchema: currentMetaData,
                    changes: action === "create" ? null : changes,
                    ddl,
                    blockedChanges: this.deriveBlockedChanges(changes, config),
                });
            }
            return { tables, numberFormat, rowCount: Array.isArray(data) ? data.length : 0 };
        }));
    }

    // Changes autosql would refuse without an explicit opt-in — the same gates
    // warnBlockedSchemaChanges enforces at load time, surfaced here so a preview can flag them.
    private deriveBlockedChanges(changes: AlterTableChanges | null, config: DatabaseConfig): string[] {
        if (!changes) return [];
        const blocked: string[] = [];
        if (changes.dropColumns?.length && !config.deleteColumns) {
            blocked.push(`Would DROP column(s) ${changes.dropColumns.join(", ")} — blocked; set deleteColumns: true to allow.`);
        }
        if (changes.primaryKeyChanges?.length && !config.updatePrimaryKey) {
            blocked.push(`Would change the primary key (${changes.primaryKeyChanges.join(", ")}) — blocked; set updatePrimaryKey: true to allow.`);
        }
        if (changes.noLongerUnique?.length && !config.dropUniqueConstraints) {
            blocked.push(`Would DROP the unique constraint on ${changes.noLongerUnique.join(", ")} — blocked; set dropUniqueConstraints: true to allow.`);
        }
        return blocked;
    }

    async autoCreateTable(table: string, newMetaData: MetadataHeader, tableExists?: boolean, runQuery: boolean = true): Promise<QueryResult | QueryInput[]> {
        try {
            if (tableExists === undefined) {
                const checkTableExistsQuery = this.db.getTableExistsQuery(this.db.getConfig().schema || this.db.getConfig().database || "", table);
                const checkTableExists = await this.db.runQuery(checkTableExistsQuery);
                if (!checkTableExists.success || !checkTableExists.results) {
                    throw new Error(`Failed to check schema existence: ${checkTableExists.error}`);
                }
                tableExists = Boolean(Number(checkTableExists?.results[0]?.count));
            }
    
            if (tableExists) {
                throw new Error("Table already exists");
            }
    
            const createQuery = this.db.getCreateTableQuery(table, newMetaData);
            if(!runQuery) {
                return createQuery
            }
            const createTable = await this.db.runTransaction(createQuery);
    
            return createTable;
    
        } catch (error) {
            throw error
        }
    }    
    
    async autoAlterTable(table: string, tableChanges: AlterTableChanges, tableExists?: boolean, runQuery: boolean = true): Promise<QueryResult | QueryInput[]> {
        try {
            if (tableExists === undefined) {
                const checkTableExistsQuery = this.db.getTableExistsQuery(this.db.getConfig().schema || this.db.getConfig().database || "", table);
                const checkTableExists = await this.db.runQuery(checkTableExistsQuery);
                if (!checkTableExists.success || !checkTableExists.results) {
                    throw new Error(`Failed to check schema existence: ${checkTableExists.error}`);
                }
                tableExists = Boolean(Number(checkTableExists?.results[0]?.count));
            }
    
            if (!tableExists) {
                throw new Error("Table doesn't exist");
            }
    
            const alterQuery = await this.db.getAlterTableQuery(table, tableChanges);
            if(!runQuery) {
                return alterQuery
            }
            const alterTable = await this.db.runTransaction(alterQuery);
    
            return alterTable
    
        } catch (error) {
            throw error
        }
    }    

    async autoConfigureTable(inputOrTable: string | InsertInput, inputData?: Record<string, any>[] | null, inputCurrentMetaData?: MetadataHeader | AlterTableChanges | null, inputNewMetaData?: MetadataHeader | null, inputRunQuery: boolean = true): Promise<QueryResult | QueryInput[]> {
        const start = new Date();
        try {
            let table: string;
            let data: Record<string, any>[] | null = null;
            let currentMetaDataOrTableChanges: MetadataHeader | AlterTableChanges | null = null;
            let newMetaData: MetadataHeader | null = null;
            let runQuery: boolean = true

            if (typeof inputOrTable === "object") {
                table = inputOrTable.table;
                data = inputOrTable.data;
                currentMetaDataOrTableChanges = inputOrTable.previousMetaData;
                newMetaData = inputOrTable.metaData;
                runQuery = inputOrTable.runQuery ?? inputRunQuery ?? true
            } else {
                table = inputOrTable;
                data = inputData ?? null;
                currentMetaDataOrTableChanges = inputCurrentMetaData ?? null;
                newMetaData = inputNewMetaData ?? null;
                runQuery = inputRunQuery
            }
            this.db.log(`[autoConfigureTable] Running for table: ${table}`);

            if (!newMetaData && data?.length === 0) {
                throw new Error(`No existing metadata and no data provided to infer structure.`);
            }
            let tableChanges: AlterTableChanges | null = null;
            let updatedMetadata: MetadataHeader | undefined | null = newMetaData;
            let tableExists: boolean | undefined = undefined;
            const inferredHere = !newMetaData;
            if(!newMetaData) {
                if(!data || !isValidDataFormat(data)) {throw new Error('Invalid data format: Expected a non-empty array of objects.')}
                newMetaData = await getMetaData(this.db.getConfig(), data);
                updatedMetadata = newMetaData
                this.db.updateTableMetadata(table, newMetaData, "metaData");
            }

            if(!updatedMetadata) { throw new Error('An unexpected error occurred while getting metadata')}

            if(!currentMetaDataOrTableChanges) {
                this.db.log("Fetching metadata since no current metadata was provided...");
                const { currentMetaData, tableExists: exists } = await this.fetchTableMetadata(table);
                tableExists = exists;

                // Standalone path (metadata inferred above, not supplied by the caller): apply the
                // opt-in surrogate key now that the existing table is known, so it stays sticky.
                updatedMetadata = applySurrogateKey(updatedMetadata, currentMetaData, this.db.getConfig());
                if (inferredHere) updatedMetadata = restrictInferredUniques(updatedMetadata, currentMetaData, this.db.getConfig());

                if (currentMetaData) {
                    const { changes, updatedMetaData: mergedMetadata } = compareMetaData(
                        currentMetaData,
                        updatedMetadata,
                        this.db.getDialectConfig(),
                        this.db.getConfig().logger
                    );
                    tableChanges = changes;
                    updatedMetadata = mergedMetadata;
                    this.db.updateTableMetadata(table, updatedMetadata, "metaData");
                }
            }
            else if(isMetadataHeader(currentMetaDataOrTableChanges)) {
                this.db.log("Comparing metadata for changes...");
                if (inferredHere) newMetaData = restrictInferredUniques(newMetaData, currentMetaDataOrTableChanges, this.db.getConfig());
                const { changes, updatedMetaData: mergedMetadata } = compareMetaData(currentMetaDataOrTableChanges, newMetaData, this.db.getDialectConfig(), this.db.getConfig().logger);
                tableChanges = changes;
                updatedMetadata = mergedMetadata;
                tableExists = true;
            } else {
                this.db.log("Precomputed table changes detected, using them directly.");
                tableChanges = currentMetaDataOrTableChanges;
                updatedMetadata = newMetaData; // No merging needed
                tableExists = true;
            }

            if (!tableExists) {
                this.db.log(`Creating table: ${table}`);
                return await this.autoCreateTable(table, updatedMetadata, false, runQuery);
            }

            // R8 (opt-in): migrate a pre-existing table's text columns to utf8mb4 so externally
            // created 3-byte utf8 columns accept 4-byte chars. Real table only, before any other
            // ALTER. Best-effort: a failed CONVERT (e.g. an over-long index) is logged and skipped.
            const stagingPrefix = this.db.getConfig().stagingPrefix ?? "temp_staging__";
            if (this.db.getConfig().upgradeCharset && !table.startsWith(stagingPrefix)) {
                try {
                    const charsetQueries = await this.db.getCharsetUpgradeQueries(table);
                    if (charsetQueries.length > 0) {
                        await this.db.runTransaction(charsetQueries);
                        this.db.log(`[autoConfigureTable] Upgraded existing charset for '${table}'.`);
                    }
                } catch (charsetErr) {
                    this.db.warn(`[autoConfigureTable] Charset upgrade for '${table}' skipped (continuing): ${charsetErr instanceof Error ? charsetErr.message : String(charsetErr)}`);
                }
            }

            if (!tableChanges || !tableChangesExist(tableChanges)) {
                this.db.log(`Table exists, no changes detected. Skipping ALTER TABLE.`);
                const end = new Date();
                const affectedRows = 0;
                const rows: any[] = []
                return {
                    start,
                    end,
                    duration: end.getTime() - start.getTime(),
                    affectedRows,
                    success: true,
                    results: rows
                };
            }
    
            this.db.log(`Altering table: ${table} with changes: ${JSON.stringify(tableChanges)}`);
            return await this.autoAlterTable(table, tableChanges, true, runQuery);
        } catch (error) {
            const end = new Date();
            const affectedRows = 0;
            return {
                start,
                end,
                duration: end.getTime() - start.getTime(),
                affectedRows,
                success: false,
                error: error instanceof Error ? error.message : String(error),
                table: typeof inputOrTable === "object" ? inputOrTable.table : inputOrTable
            };
        }
    }

    async fetchTableMetadata(table: string): Promise<{ currentMetaData: MetadataHeader | null; tableExists: boolean; }> {
        // One introspection round-trip, not two: the column-metadata query already says whether the
        // table exists (a missing table returns 0 rows), and INFORMATION_SCHEMA lookups are slow.
        const schema = this.db.getConfig().schema || this.db.getConfig().database || "";
        const currentMetaDataQuery = this.db.getTableMetaDataQuery(schema, table);
        const currentMetaDataResults = await this.db.runQuery(currentMetaDataQuery);

        if (!currentMetaDataResults || !currentMetaDataResults.success) {
            throw new Error(`Failed to retrieve existing meta data for table ${table}: ${currentMetaDataResults?.error ?? "unknown error"}`);
        }

        const rows = currentMetaDataResults.results ?? [];
        const tableExists = rows.length > 0;
        let currentMetaData: MetadataHeader | null = null;

        if (tableExists) {
            const parsedMetadata = parseDatabaseMetaData(rows, this.db.getDialectConfig());

            if (!parsedMetadata) {
                currentMetaData = null;
            } else if (typeof parsedMetadata === "object" && !Array.isArray(parsedMetadata)) {
                currentMetaData = parsedMetadata as MetadataHeader;
            } else {
                throw new Error("Unexpected metadata format: Multiple tables returned for a single-table query.");
            }

            if (currentMetaData) {
                this.db.updateTableMetadata(table, currentMetaData, "existingMetaData");
            }
        }

        return { currentMetaData, tableExists };
    }

    async splitTableData(table: string, data: Record<string, any>[], metaData: MetadataHeader): Promise<{table: string, data: Record<string, any>[], metaData: MetadataHeader, previousMetaData: MetadataHeader, mergedMetaData: { changes: AlterTableChanges, updatedMetaData: MetadataHeader }}[]> {
        try {
            const splitQuery = this.db.getSplitTablesQuery(table);
            const currentSplitResults = await this.db.runQuery(splitQuery);
            if(!currentSplitResults || !currentSplitResults.success || !currentSplitResults.results) { throw new Error(currentSplitResults.error || `Error while retrieving existing split table information for: ${table}`)}
            const currentSplit = currentSplitResults.results
            const rawSplitMetadata = parseDatabaseMetaData(currentSplit as Record<string, any>[], this.db.getDialectConfig());
            let parsedSplitMetadata: Record<string, MetadataHeader>;
            if (!rawSplitMetadata) {
                parsedSplitMetadata = { [table]: {} }; // Ensure it has a valid structure
            } else if (Object.values(rawSplitMetadata).some(value => typeof value === "object" && !Array.isArray(value))) {
                parsedSplitMetadata = rawSplitMetadata as Record<string, MetadataHeader>;
            } else {
                parsedSplitMetadata = { [table]: rawSplitMetadata as MetadataHeader };
            }
            const newGroupedByTable = organizeSplitTable(table, metaData, parsedSplitMetadata, this.db.getDialectConfig())
            const newGroupedData = organizeSplitData(data, newGroupedByTable)
            const transformedData = await Promise.all(
                Object.keys(newGroupedByTable).map(async (tableName) => {
                    const newMetaData = restrictInferredUniques(await getMetaData(this.db.getConfig(), newGroupedData[tableName] || []), parsedSplitMetadata[tableName], this.db.getConfig());
                    const mergedMetaData = compareMetaData(parsedSplitMetadata[tableName], newMetaData, this.db.getDialectConfig(), this.db.getConfig().logger);
            
                    return {
                        table: tableName,
                        data: newGroupedData[tableName] || [],
                        metaData: newMetaData,
                        previousMetaData: parsedSplitMetadata[tableName],
                        mergedMetaData: mergedMetaData
                    };
                })
            );
            return transformedData
        } catch (error) {
            throw error
        }
    }

    async autoInsertData(inputOrTable: InsertInput | string, inputData?: Record<string, any>[], inputMetaData?: MetadataHeader, inputPreviousMetaData?: AlterTableChanges | MetadataHeader | null, inputComparedMetaData?: { changes: AlterTableChanges, updatedMetaData: MetadataHeader }, inputRunQuery: boolean = true, inputInsertType?: "UPDATE" | "INSERT"): Promise<QueryInput[] | QueryResult> {
        let table: string;
        let data: Record<string, any>[] = [];
        let metaData: MetadataHeader;
        // Accepted via inputPreviousMetaData for API compatibility but not otherwise read in this
        // method; comparedMetaData/effectiveMetaData carry what the insert path actually needs.
        let _previousMetaData: AlterTableChanges | MetadataHeader | null = null;
        let comparedMetaData: { changes: AlterTableChanges, updatedMetaData: MetadataHeader } | undefined;
        let runQuery: boolean;
        let insertType: "UPDATE" | "INSERT"

        // Fall back to configured insertType (then "UPDATE") so the direct-insert path honours
        // `config.insertType`. It previously defaulted straight to "UPDATE", so an "INSERT" config
        // was silently ignored for the bulk batch while the per-row fallback honoured it.
        const configInsertType = this.db.getConfig().insertType;

        if (typeof inputOrTable === "object" && "table" in inputOrTable && "data" in inputOrTable) {
          table = inputOrTable.table;
          data = inputOrTable.data;
          metaData = inputOrTable.metaData;
          _previousMetaData = inputOrTable.previousMetaData;
          comparedMetaData = inputOrTable.comparedMetaData;
          runQuery = inputOrTable.runQuery ?? true;
          insertType = inputOrTable?.insertType ?? configInsertType ?? "UPDATE"
        } else {
          table = inputOrTable;
          data = inputData ?? [];
          if (!inputMetaData) throw new Error(`autoInsertData: metaData is required when called with individual parameters`);
          metaData = inputMetaData;
          _previousMetaData = inputPreviousMetaData ?? null;
          comparedMetaData = inputComparedMetaData;
          runQuery = inputRunQuery ?? true
          insertType = inputInsertType ?? configInsertType ?? "UPDATE"
        }
        if (data.length === 0) {
            throw new Error(`insertData: no data rows provided for table "${table}"`);
        }          

        const splitData: Record<string, any>[][] = splitInsertData(data, this.db.getConfig())
        const effectiveMetaData = comparedMetaData?.updatedMetaData || metaData;
        
        // getInsertStatementQuery is synchronous on every dialect — no await-worthy work happens
        // per chunk, so this is a plain map, not a Promise.all over non-Promise values.
        const insertStatements: QueryInput[] = splitData.map((chunk) => {
            const normalisedChunk = chunk.map((row) =>
              getInsertValues(effectiveMetaData, row, this.db.getDialectConfig(), this.db.getConfig(), true)
            );
            return this.db.getInsertStatementQuery(table, normalisedChunk, effectiveMetaData, insertType);
          });

        if (insertStatements.length > 0 && runQuery) {
            return this.db.runTransaction(insertStatements);
        }
        return insertStatements;
    }

    async handleMetadata(table: string, data: Record<string, any>[], primaryKey?: string[], options?: AutoSQLOptions) {
        // With `existingSchema` (N1 fast path) trust the caller and skip live introspection, the main
        // per-run round-trip for a stable pipeline. It must be a prior run's RESOLVED schema, so it
        // already carries the managed dwh_*/surrogate columns and the timestamp step won't re-add them.
        const currentMetaData = options?.existingSchema
            ?? (await this.fetchTableMetadata(table)).currentMetaData;

        // A-4 fast path: `assumeSchema` is authoritative. Declaring every data column skips per-value
        // inference entirely; partial coverage infers the rest and lets the provided definitions win.
        // Also side-steps inference footguns (e.g. small ints mis-typed as boolean).
        let newMetaData: MetadataHeader;
        const assumeSchema = options?.assumeSchema;
        if (assumeSchema && Object.keys(assumeSchema).length > 0) {
            const provided = fillColumnDefaults(assumeSchema);
            if (schemaCoversColumns(provided, collectDataColumns(data))) {
                newMetaData = provided; // fully declared → no inference
            } else {
                const inferred = restrictInferredUniques(await getMetaData(this.db.getConfig(), data, primaryKey), currentMetaData, this.db.getConfig());
                newMetaData = overlaySchema(inferred, provided); // infer undeclared, provided wins
            }
        } else {
            // inferAdditionalUniques: false → on an existing table, inferred uniques only survive where the live column has one.
            newMetaData = restrictInferredUniques(await getMetaData(this.db.getConfig(), data, primaryKey), currentMetaData, this.db.getConfig());
        }
        // Apply the opt-in surrogate key, sticky to the existing table so re-ingestion stays
        // idempotent (see applySurrogateKey). No-op unless config.surrogateKey is enabled.
        newMetaData = applySurrogateKey(newMetaData, currentMetaData, this.db.getConfig());
        this.db.updateTableMetadata(table, newMetaData, "metaData");

        let initialComparedMetaData : { changes: AlterTableChanges; updatedMetaData: MetadataHeader } | undefined;
        let mergedMetaData: MetadataHeader = newMetaData;
        let changes: AlterTableChanges | null = null;

        if (currentMetaData) {
            initialComparedMetaData  = compareMetaData(currentMetaData, newMetaData, this.db.getDialectConfig(), this.db.getConfig().logger);
            changes = initialComparedMetaData .changes;
            mergedMetaData = initialComparedMetaData.updatedMetaData;
            this.db.updateTableMetadata(table, mergedMetaData, "metaData");
        }

        // Add the dwh_* timestamps AFTER comparison so they carry the calculatedDefault that
        // populates them on insert; comparing first would merge in the value-less introspected
        // definition on re-ingest and insert NULL. On an existing table a dwh column not already
        // there is genuinely new and must join addColumns, or the staging copy fails.
        const beforeTimestamps = new Set(Object.keys(mergedMetaData));
        mergedMetaData = ensureTimestamps(this.db.getConfig(), mergedMetaData, new Date());
        if (currentMetaData && initialComparedMetaData) {
            for (const col of Object.keys(mergedMetaData)) {
                if (!beforeTimestamps.has(col) && !(col in currentMetaData)) {
                    initialComparedMetaData.changes.addColumns[col] = mergedMetaData[col];
                }
            }
            changes = initialComparedMetaData.changes;
            this.db.updateTableMetadata(table, mergedMetaData, "metaData");
        }
    
        return { currentMetaData, mergedMetaData, initialComparedMetaData, changes, newMetaData };
    }

    private async attemptTableSplit(table: string, data: Record<string, any>[], mergedMetaData: MetadataHeader) {
        if (this.db.getConfig().autoSplit) {
            const { exceedsLimit } = estimateRowSize(mergedMetaData, this.db.getDialect());
            const columnCount = Object.keys(mergedMetaData).length;
            const exceedsColumnLimit = columnCount >= MAX_COLUMN_COUNT;
    
            if (exceedsLimit || exceedsColumnLimit) {
                return this.splitTableData(table, data, mergedMetaData);
            }
        }
        return [];
    }

    private async prepareInsertData(table: string, data: Record<string, any>[], schema?: string, primaryKey?: string[], options?: AutoSQLOptions): Promise<InsertInput[]> {
        // Step 1: Handle Metadata
        const { currentMetaData, mergedMetaData, initialComparedMetaData, changes, newMetaData } = await this.handleMetadata(table, data, primaryKey, options);
    
        // Step 2: Attempt Table Split
        let insertInput: InsertInput[] = await this.attemptTableSplit(table, data, mergedMetaData);
    
        // Step 3: Handle the case when split is not needed or failed
        if (!insertInput || insertInput.length === 0) {
            // Step 3.1: Handle metadata comparison if not split
            let comparedMetaData = initialComparedMetaData;
            if (comparedMetaData === undefined) {
                comparedMetaData = compareMetaData(currentMetaData || null, newMetaData, this.db.getDialectConfig(), this.db.getConfig().logger);
            }
    
            insertInput = [{
                table,
                data,
                previousMetaData: changes || currentMetaData,
                metaData: mergedMetaData,
                comparedMetaData,
                stagingPrefix: this.db.getConfig().stagingPrefix,
                historyTableSuffix: this.db.getConfig().historyTableSuffix
            }];
        }
    
        return insertInput;
    }
    
    private async configureTables(insertInput: InsertInput[]): Promise<QueryResult[]> {
        if (this.db.getConfig().safeMode) return [];
    
        let configuredTables: (QueryResult | QueryInput[])[];
    
        // Step 1: Auto-configure tables (with Workers or Directly). Only fan out to workers when
        // there's more than one table to configure — a single table isn't worth a worker pool (A8).
        if (this.db.getConfig().useWorkers && insertInput.length > 1) {
            insertInput = insertInput.map((input) => ({ ...input, runQuery: false }));
            try {
                const workerResults = await WorkerHelper.run(this.db.getConfig(), "autoConfigureTable", insertInput) as { success: boolean; result: QueryResult | QueryInput[], error?: string | Error, errorCode?: string }[];

                const failed = workerResults.filter(w => !w.success);
                if (failed.length > 0) {
                    const err = new Error(
                        `Worker execution failed for ${failed.length} task(s):\n` +
                        failed.map((f, i) => `- Task #${i + 1}: ${typeof f?.error === "string" ? f.error : (f?.error?.message || "Unknown Error")}`).join("\n")
                    ) as Error & { code?: string };
                    const withCode = failed.find(f => f.errorCode);
                    if (withCode?.errorCode) err.code = withCode.errorCode;
                    throw err;
                }

                configuredTables = workerResults.map(w => w.result);
            } catch (err) {
                if (err instanceof Error && err.message.startsWith("WORKER_UNAVAILABLE:")) {
                    this.db.warn(err.message + " Falling back to direct execution.");
                    configuredTables = await Promise.all(insertInput.map((input) => this.autoConfigureTable(input)));
                } else {
                    throw err;
                }
            }
        } else {
            configuredTables = await Promise.all(insertInput.map((input) => this.autoConfigureTable(input)));
        }
    
        // Step 2: Split immediate results from deferred DDL queries, preserving
        //    index correspondence with insertInput for rollback correlation.
        const initialResults: QueryResult[] = [];
        const pendingDDL: Array<{ queries: QueryInput[]; inputIndex: number }> = [];

        configuredTables.forEach((result, i) => {
            if (Array.isArray(result)) {
                pendingDDL.push({ queries: result, inputIndex: i });
            } else {
                initialResults.push(result);
            }
        });

        // Step 3: Execute DDL transactions and attempt compensating rollback on failure
        let allResults: QueryResult[];
        if (pendingDDL.length > 0) {
            const transactionResults: QueryResult[] = await this.db.runTransactionsWithConcurrency(
                pendingDDL.map(d => d.queries)
            );

            // Best-effort compensating DDL for failed transactions. No-op on Postgres (transactional
            // DDL already rolled back); on MySQL it reverses partial schema changes.
            const failedDDL = transactionResults
                .map((result, j) => (!result.success ? pendingDDL[j] : null))
                .filter((x): x is { queries: QueryInput[]; inputIndex: number } => x !== null);

            if (failedDDL.length > 0) {
                for (const { inputIndex } of failedDDL) {
                    const input = insertInput[inputIndex];
                    if (input?.comparedMetaData) {
                        const { queries: compQueries, warnings } = buildCompensatingDDL(
                            input.table,
                            input.comparedMetaData.changes,
                            input.comparedMetaData.updatedMetaData,
                            this.db.getDialectConfig(),
                            this.db.getConfig().schema
                        );
                        for (const w of warnings) this.db.warn(w);
                        if (compQueries.length > 0) {
                            await this.db.runTransaction(compQueries).catch(e =>
                                this.db.error(`DDL compensation failed for '${input.table}': ${e.message}`)
                            );
                        }
                    }
                }
            }

            allResults = [...initialResults, ...transactionResults];
        } else {
            allResults = [...initialResults];
        }

        // Step 4: Handle failures
        throwIfFailedResults(allResults, "table configuring queries")
    
        this.db.log("All tables configured and executed successfully.");
        return allResults;
    }

    private async insertData(insertInput: InsertInput[], options?: { perRowFallback?: boolean }): Promise<QueryResult[]> {
        if (insertInput.length === 0) {
            throw new Error("No data found for insert after tables were configured");
        }
    
        let insertQueries: (QueryResult | QueryInput[])[];
    
        // Step 1: Handle single insert separately
        if (insertInput.length === 1) {
            insertQueries = [
                await this.autoInsertData({ ...insertInput[0], runQuery: false })
            ];
        } else {
            // Step 2: Defer execution & modify inputs
            insertInput = insertInput.map((input) => ({ ...input, runQuery: false }));

            if (this.db.getConfig().useWorkers && insertInput.length > 1) {
                try {
                    const workerResults = await WorkerHelper.run(this.db.getConfig(), "autoInsertData", insertInput) as { success: boolean; result: QueryResult | QueryInput[], error?: string | Error, errorCode?: string }[];

                    const failed = workerResults.filter(w => !w.success);
                    if (failed.length > 0) {
                        const err = new Error(
                            `Worker execution failed for ${failed.length} task(s):\n` +
                            failed.map((f, i) => `- Task #${i + 1}: ${typeof f?.error === "string" ? f.error : (f?.error?.message || "Unknown Error")}`).join("\n")
                        ) as Error & { code?: string };
                        const withCode = failed.find(f => f.errorCode);
                        if (withCode?.errorCode) err.code = withCode.errorCode;
                        throw err;
                    }

                    insertQueries = workerResults.map(w => w.result);
                } catch (err) {
                    if (err instanceof Error && err.message.startsWith("WORKER_UNAVAILABLE:")) {
                        this.db.warn(err.message + " Falling back to direct execution.");
                        insertQueries = await Promise.all(
                            insertInput.map((input) => this.autoInsertData({ ...input, runQuery: false }))
                        );
                    } else {
                        throw err;
                    }
                }
            } else {
                insertQueries = await Promise.all(
                    insertInput.map((input) => this.autoInsertData({ ...input, runQuery: false }))
                );
            }
        }
    
        // Step 3: Execute Insert Transactions
        const insertTransactionInputs: QueryInput[][] = insertQueries as QueryInput[][];
        const allInsertResults: QueryResult[] = await this.db.runTransactionsWithConcurrency(insertTransactionInputs);
    
        // Step 4: Handle Failures
        // Graceful degradation is opt-in and only for the non-atomic direct-insert path: the caller
        // passes perRowFallback and the user configured rejectedRowsTable. Without it a failed batch
        // throws, which is right when the caller hasn't said where bad rows should go.
        const config = this.db.getConfig();
        if (options?.perRowFallback && config.rejectedRowsTable && allInsertResults.some(r => !r?.success)) {
            return this.degradation.applyPerRowFallback(insertInput, allInsertResults);
        }

        throwIfFailedResults(allInsertResults, "data insert queries")

        return allInsertResults;
    }

    private async extractNestedInputs(inputs: InsertInput[]): Promise<InsertInput[]> {
        if(!this.db.getConfig().addNested) { 
            return []
        }
        const nestedInputs: InsertInput[] = [];
        const nestedMap: Record<string, Record<string, any>[]> = {};
        const primaryMap: Record<string, string[]> = {};

        for (const input of inputs) {
          const { table, data, metaData } = input;
          const primaryKeys = Object.keys(metaData).filter(k => metaData[k].primary);
      
          for (const row of data) {
            for (const [key, value] of Object.entries(row)) {
                const nestedTable = `${table}_${key}`;
                if(!this.db.getConfig().nestedTables?.includes(nestedTable)) { continue; }
              if (value && typeof value === "object") {

                const nestedObjects: Record<string, any>[] = Array.isArray(value)
                    ? value.filter(v => typeof v === "object" && !Array.isArray(v))
                    : [value];
                
                for (const nested of nestedObjects) {
                    const newRow = {
                      ...nested,
                      ...Object.fromEntries(primaryKeys.map(pk => [pk, row[pk]]))
                    };
                
                    if (!nestedMap[nestedTable]) {
                        nestedMap[nestedTable] = [];
                    }
                    if(!primaryMap[nestedTable]) {
                        primaryMap[nestedTable] = primaryKeys
                    }
                    nestedMap[nestedTable].push(newRow);
                }
              }
            }
          }
        }
      
        for (const [nestedTable, nestedRows] of Object.entries(nestedMap)) {
            const { currentMetaData, mergedMetaData, initialComparedMetaData, changes, newMetaData } = await this.handleMetadata(nestedTable, nestedRows, primaryMap[nestedTable]);
            let comparedMetaData = initialComparedMetaData;
            if (comparedMetaData === undefined) {
                comparedMetaData = compareMetaData(currentMetaData || null, newMetaData, this.db.getDialectConfig(), this.db.getConfig().logger);
            }
            const insertInput : InsertInput = {
                table: nestedTable,
                data: nestedRows,
                previousMetaData: changes || currentMetaData,
                metaData: mergedMetaData,
                comparedMetaData,
                stagingPrefix: this.db.getConfig().stagingPrefix,
                historyTableSuffix: this.db.getConfig().historyTableSuffix,
            };
            nestedInputs.push(insertInput);
        }
        return nestedInputs;
    } 
    
    async autoSQL(table: string, data: Record<string, any>[], schema?: string, primaryKey?: string[], options?: AutoSQLOptions): Promise<QueryResult> {
      // Resolve dataset-level number format ONCE, before inference, and run the whole load under it
      // so inference, staging, direct insert, and workers all sqlize with the same separators.
      const separators = this.resolveSeparatorConsensus(data);
      return this.db.runWithSeparators(separators, () => this.db.runWithSchema(schema, async () => {
        const start = new Date();
        const config = this.db.getConfig();
        const useSchemaLock = config.useSchemaLock;
        const lockTimeout = config.schemaLockTimeout ?? DEFAULTS.schemaLockTimeout;
        const useHistory = config.schemaHistory;

        try {
            let affectedRows: number;
            let insertResults: QueryResult[];
            let insertInput: InsertInput[];

            // Per-run instrumentation (QueryStats): wall-clock per phase. `perf` is monotonic and
            // sub-millisecond, independent of the Date-based start/end used for the result envelope.
            const perf = () => (typeof performance !== "undefined" ? performance.now() : Date.now());
            const phases: { prepare?: number; configure?: number; load?: number } = {};

            if (useSchemaLock) await this.db.acquireSchemaLock(table, lockTimeout);
            let historyId: number | undefined;
            try {
                const tPrepare = perf();
                insertInput = await this.prepareInsertData(table, data, schema, primaryKey, options);
                let nestedInputs = await this.extractNestedInputs(insertInput);
                insertInput = [...insertInput, ...nestedInputs];
                phases.prepare = perf() - tPrepare;

                // Schema history: drift detection + record start
                if (useHistory) {
                    if (config.detectDrift ?? true) {
                        await this.history.detectDrift(table);
                    }
                    await this.history.bootstrap();
                    const primary = insertInput[0];
                    if (primary?.comparedMetaData && tableChangesExist(primary.comparedMetaData.changes)) {
                        historyId = await this.history.recordStart(
                            table,
                            (primary.previousMetaData && !Array.isArray(primary.previousMetaData) && 'addColumns' in primary.previousMetaData ? {} : primary.previousMetaData) as any || {},
                            primary.comparedMetaData.changes
                        );
                    }
                }

                try {
                    const tConfigure = perf();
                    await this.configureTables(insertInput);
                    phases.configure = perf() - tConfigure;
                    if (historyId !== undefined) {
                        const updatedMeta = insertInput[0]?.comparedMetaData?.updatedMetaData;
                        if (updatedMeta) {
                            // Store the drift baseline as the checksum of the RE-INTROSPECTED table, not
                            // the inferred `updatedMeta` — drift detection next run reads the introspected
                            // schema, and inferred-vs-introspected would false-positive on legitimate type
                            // round-trips (A6). `new_schema` stays `updatedMeta` (inferred) for
                            // point-in-time reconstruction; a null introspection stores a null checksum
                            // (treated as "no baseline"), which also covers the A19 couldn't-read case.
                            const liveMeta = await this.db.getTableMetaData(config.schema || config.database || "", table);
                            await this.history.recordSuccess(historyId, updatedMeta, liveMeta);
                        }
                        else await this.history.recordRolledBack(historyId);
                    }
                } catch (ddlErr) {
                    if (historyId !== undefined) {
                        await this.history.recordFailed(historyId).catch(() => {});
                    }
                    throw ddlErr;
                }
            } finally {
                if (useSchemaLock) await this.db.releaseSchemaLock(table);
            }

            const tLoad = perf();
            insertResults = await this.strategy.load({ insertInput, table, label: 'autoSQL' });
            phases.load = perf() - tLoad;

            affectedRows = insertResults.reduce((sum, res) => sum + (res.affectedRows || 0), 0);
            const allResults = insertResults.flatMap(res => res.results || []);
            const end = new Date();
            // Return the resolved schema (incl. managed dwh_*/surrogate columns) so callers can
            // cache it and skip re-introspection next load — the `existingSchema` fast path.
            const resolvedMetaData = insertInput[0]?.comparedMetaData?.updatedMetaData || insertInput[0]?.metaData;

            // Attach metrics to the result and emit to the structured stats sink if configured.
            const durationMs = end.getTime() - start.getTime();
            const stats: QueryStats = {
                table,
                rows: data.length,
                affectedRows,
                durationMs,
                rowsPerSecond: durationMs > 0 ? Math.round((data.length / durationMs) * 1000) : 0,
                phases: {
                    prepare: phases.prepare !== undefined ? Math.round(phases.prepare) : undefined,
                    configure: phases.configure !== undefined ? Math.round(phases.configure) : undefined,
                    load: phases.load !== undefined ? Math.round(phases.load) : undefined,
                },
                staged: !!config.useStagingInsert,
                bulkLoad: !!config.bulkLoad,
            };
            try { config.logger?.stats?.(stats); } catch { /* a metrics sink must never break a load */ }
            await writeRunAudit(this.db, { table, success: true, rows: data.length, affectedRows, durationMs, rowsPerSecond: stats.rowsPerSecond, phases: stats.phases, staged: stats.staged, bulkLoad: stats.bulkLoad });

            return { start, end, success: true, duration: durationMs, affectedRows, results: allResults, table, metaData: resolvedMetaData, stats };
        } catch (error: any) {
            const end = new Date();
            const durationMs = end.getTime() - start.getTime();
            await writeRunAudit(this.db, { table, success: false, rows: data.length, affectedRows: 0, durationMs, rowsPerSecond: 0, staged: !!config.useStagingInsert, bulkLoad: !!config.bulkLoad, error: error instanceof Error ? error.message : String(error), errorCode: error?.code != null ? String(error.code) : undefined });
            return { start, end, duration: durationMs, affectedRows: 0, success: false, error: error instanceof Error ? error.message : String(error), errorCode: error?.code != null ? String(error.code) : undefined };
        }
      }));
    }

    /**
     * Insert data from an async iterable of chunks into a table.
     *
     * The first chunk drives full schema inference and table configuration; later chunks reuse that
     * schema, bypassing inference and DDL. With `useSchemaLock: true` the advisory lock is held only
     * for the first-chunk inference and DDL, then released before inserts begin.
     *
     * @param table     Target table name
     * @param chunks    Async iterable of row arrays (each array is one chunk)
     * @param schema    Optional schema/database override for this call
     * @param primaryKey Optional primary key hint passed to schema inference
     */
    async autoSQLChunked(
        table: string,
        chunks: AsyncIterable<Record<string, any>[]>,
        schema?: string,
        primaryKey?: string[]
    ): Promise<QueryResult> {
      return this.db.runWithSchema(schema, async () => {
        const start = new Date();

        // Dataset-level number format is resolved ONCE from the first non-empty chunk and LOCKED for
        // the whole load (across chunks only column lengths grow, never the format). Peek that chunk,
        // resolve, then process it and the rest under the resolved separators.
        const iterator = chunks[Symbol.asyncIterator]();
        let pending = await iterator.next();
        while (!pending.done && pending.value.length === 0) pending = await iterator.next();
        const firstValue: Record<string, any>[] | null = pending.done ? null : pending.value;
        const separators = firstValue ? this.resolveSeparatorConsensus(firstValue) : undefined;
        const remaining: AsyncIterable<Record<string, any>[]> = {
            async *[Symbol.asyncIterator]() {
                try {
                    if (firstValue !== null) yield firstValue;
                    let r; while (!(r = await iterator.next()).done) yield r.value;
                } finally {
                    // Forward early termination to the SOURCE iterator so a cursor-backed `chunks`
                    // runs its own cleanup. We took over manual iteration for the first-chunk peek,
                    // so the for-await's automatic `.return()` reaches this wrapper, not the source.
                    await iterator.return?.();
                }
            }
        };

        return this.db.runWithSeparators(separators, async () => {
        const config = this.db.getConfig();
        const useSchemaLock = config.useSchemaLock;
        const lockTimeout = config.schemaLockTimeout ?? DEFAULTS.schemaLockTimeout;

        let totalAffectedRows = 0;
        let lockedInsertInput: InsertInput[] | null = null;

        // Per-run instrumentation (QueryStats), aggregated across chunks: prepare/configure are the
        // first-chunk schema inference + DDL; load accumulates every chunk's insert time.
        const perf = () => (typeof performance !== "undefined" ? performance.now() : Date.now());
        const phases: { prepare?: number; configure?: number; load?: number } = {};
        let totalRows = 0;

        try {
            for await (const chunk of remaining) {
                if (chunk.length === 0) continue;
                totalRows += chunk.length;

                let chunkInsertInput: InsertInput[];

                if (lockedInsertInput === null) {
                    // First chunk: full schema inference + table configuration (the table is new).
                    if (useSchemaLock) await this.db.acquireSchemaLock(table, lockTimeout);
                    try {
                        const tPrepare = perf();
                        chunkInsertInput = await this.prepareInsertData(table, chunk, schema, primaryKey);
                        const nestedInputs = await this.extractNestedInputs(chunkInsertInput);
                        chunkInsertInput = [...chunkInsertInput, ...nestedInputs];
                        phases.prepare = perf() - tPrepare;
                        const tConfigure = perf();
                        await this.configureTables(chunkInsertInput);
                        phases.configure = perf() - tConfigure;
                    } finally {
                        if (useSchemaLock) await this.db.releaseSchemaLock(table);
                    }
                    lockedInsertInput = chunkInsertInput;
                } else {
                    // Later chunks reuse the locked schema but must GUARD AGAINST DRIFT: locking the
                    // first chunk's types means a later chunk can carry a value the column can't hold
                    // (ids 1..100 infer tinyint, then id 128 overflows). Re-infer this chunk and
                    // compare ONLY its data columns, since the managed columns aren't in the chunk and
                    // must not read as "to drop". Widen only when a column needs it.
                    const lockedMeta = lockedInsertInput[0].metaData;
                    const tPrepare = perf();
                    const inferred = await getMetaData(config, chunk, primaryKey);
                    phases.prepare = (phases.prepare ?? 0) + (perf() - tPrepare);

                    const lockedDataOnly: MetadataHeader = {};
                    for (const col of Object.keys(inferred)) if (lockedMeta[col]) lockedDataOnly[col] = lockedMeta[col];
                    const { changes } = compareMetaData(lockedDataOnly, inferred, this.db.getDialectConfig(), config.logger);

                    // Drift here means only "the locked column can't hold this chunk's data": a
                    // widened column (modifyColumns) or a new one (addColumns). Keys are locked from
                    // the first chunk, so a later chunk's re-evaluation must NOT drive DDL.
                    const drift = Object.keys(changes.modifyColumns).length > 0 || Object.keys(changes.addColumns).length > 0;
                    if (drift) {
                        this.db.warn(`autoSQLChunked: schema drift in a later chunk for '${table}' — widening the table to fit.`);
                        // Overlay the widened / newly-added data columns onto the full locked schema so
                        // managed columns are preserved; autoConfigureTable re-diffs and ALTERs cleanly.
                        const widened: MetadataHeader = { ...lockedMeta, ...changes.modifyColumns, ...changes.addColumns };
                        const driftInput: InsertInput = { ...lockedInsertInput[0], data: chunk, previousMetaData: lockedMeta, metaData: widened };
                        if (useSchemaLock) await this.db.acquireSchemaLock(table, lockTimeout);
                        try {
                            const tConfigure = perf();
                            await this.configureTables([driftInput]);
                            phases.configure = (phases.configure ?? 0) + (perf() - tConfigure);
                        } finally {
                            if (useSchemaLock) await this.db.releaseSchemaLock(table);
                        }
                        lockedInsertInput = lockedInsertInput.map((inp, i) => i === 0 ? { ...inp, metaData: widened } : inp);
                    }

                    chunkInsertInput = lockedInsertInput.map(input => ({ ...input, data: chunk }));
                }

                let insertResults: QueryResult[];
                const tLoad = perf();
                insertResults = await this.strategy.load({ insertInput: chunkInsertInput, table, label: 'autoSQLChunked' });
                phases.load = (phases.load ?? 0) + (perf() - tLoad);

                totalAffectedRows += insertResults.reduce((s, r) => s + (r.affectedRows || 0), 0);
            }

            const end = new Date();
            const durationMs = end.getTime() - start.getTime();
            const stats: QueryStats = {
                table,
                rows: totalRows,
                affectedRows: totalAffectedRows,
                durationMs,
                rowsPerSecond: durationMs > 0 ? Math.round((totalRows / durationMs) * 1000) : 0,
                phases: {
                    prepare: phases.prepare !== undefined ? Math.round(phases.prepare) : undefined,
                    configure: phases.configure !== undefined ? Math.round(phases.configure) : undefined,
                    load: phases.load !== undefined ? Math.round(phases.load) : undefined,
                },
                staged: !!this.db.getConfig().useStagingInsert,
                bulkLoad: !!this.db.getConfig().bulkLoad,
            };
            try { this.db.getConfig().logger?.stats?.(stats); } catch { /* a metrics sink must never break a load */ }
            await writeRunAudit(this.db, { table, success: true, rows: totalRows, affectedRows: totalAffectedRows, durationMs, rowsPerSecond: stats.rowsPerSecond, phases: stats.phases, staged: stats.staged, bulkLoad: stats.bulkLoad });
            return {
                start,
                end,
                success: true,
                duration: durationMs,
                affectedRows: totalAffectedRows,
                table,
                stats
            };
        } catch (error: any) {
            const end = new Date();
            const durationMs = end.getTime() - start.getTime();
            await writeRunAudit(this.db, { table, success: false, rows: totalRows, affectedRows: 0, durationMs, rowsPerSecond: 0, staged: !!this.db.getConfig().useStagingInsert, bulkLoad: !!this.db.getConfig().bulkLoad, error: error instanceof Error ? error.message : String(error), errorCode: error?.code != null ? String(error.code) : undefined });
            return {
                start,
                end,
                duration: durationMs,
                affectedRows: 0,
                success: false,
                error: error instanceof Error ? error.message : String(error)
            };
        }
        });
      });
    }

    /**
     * Open a streaming session and return a handle for incremental writes.
     *
     * Contract: this returns a promise that **rejects** on failure (e.g. the initial
     * connectivity check fails) and must be awaited. The returned handle's methods
     * (`write`/`end`/`abort`) follow the same reject-on-failure, must-await contract —
     * they are not fire-and-forget. See {@link AutoSQLStreamHandle.write}.
     *
     * `opts.sessionKey` opts into staging that survives between runs. See README, "Resuming a
     * stream across runs".
     */
    async openStream(
        table: string,
        schema?: string,
        primaryKey?: string[],
        opts?: OpenStreamOptions
    ): Promise<AutoSQLStreamHandle> {
      return this.db.runWithSchema(schema, async () => {
        // Connectivity check — surfaces auth/connection errors before first write
        const ping = await this.db.runQuery({ query: 'SELECT 1', params: [] });
        if (!ping.success) {
            throw new Error(`openStream: cannot connect to database — ${ping.error}`);
        }

        const config = this.db.getConfig();
        const prefix = config.streamingStagingPrefix ?? DEFAULTS.streamingStagingPrefix;

        if (!config.keepOrphanedStagingTables) {
            await this._cleanupOrphanedStreamTables(table, prefix);
        }

        const sessionKey = opts?.sessionKey;
        if (sessionKey !== undefined && sessionKey.trim() === '') {
            // Almost always an unset caller variable; accepting it would make every such caller
            // share one staging table.
            throw new Error(`openStream: sessionKey must be a non-empty string when provided.`);
        }

        if (!sessionKey) {
            const runId = generateRunId();
            const stagingTable = buildStreamStagingTableName(table, prefix, runId);
            this.activeStreamStagingTables.add(stagingTable);

            // The handle re-establishes this schema context for its own write()/end()/abort()
            // calls, which run later in separate async invocations.
            return new AutoSQLStreamHandle(this, this.db, table, stagingTable, schema, primaryKey);
        }

        const stagingTable = buildResumableStagingTableName(table, prefix, sessionKey);
        this.activeStreamStagingTables.add(stagingTable);

        // Null when the table isn't there yet, which is the normal first run for a key.
        const adoptedColumns = await this._probeStagingColumns(stagingTable);

        return new AutoSQLStreamHandle(
            this, this.db, table, stagingTable, schema, primaryKey,
            { resumable: true, adoptedColumns }
        );
      });
    }

    /** Column names of an existing stream staging table, or `null` if it isn't there. */
    async _probeStagingColumns(stagingTable: string): Promise<string[] | null> {
        const config = this.db.getConfig();
        const result = await this.db.runQuery(buildStagingColumnsQuery(stagingTable, config));
        if (!result.success) {
            throw new Error(`openStream: failed to inspect existing staging table '${stagingTable}': ${result.error}`);
        }
        if (!result.results?.length) return null;
        // The handle tracks the CALLER's shape; these would look like data downstream.
        return result.results
            .map((r: any) => r.column_name ?? r.COLUMN_NAME)
            .filter((c: string) => !isStagingMetaColumn(c));
    }

    async _cleanupOrphanedStreamTables(table: string, prefix: string): Promise<void> {
        const config = this.db.getConfig();
        const dialect = config.sqlDialect;
        const schema = config.schema || config.database || '';
        const pattern = `${prefix}${table}__%`;
        const q = dialect === 'mysql'
            ? { query: `SELECT table_name FROM information_schema.tables WHERE table_schema = ? AND table_name LIKE ?`, params: [schema, pattern] }
            : dialect === 'sqlserver'
            ? { query: `SELECT table_name FROM information_schema.tables WHERE table_schema = @p0 AND table_name LIKE @p1`, params: [schema, pattern] }
            : { query: `SELECT table_name FROM information_schema.tables WHERE table_schema = $1 AND table_name LIKE $2`, params: [schema, pattern] };

        const result = await this.db.runQuery(q);
        if (!result.success || !result.results?.length) return;

        for (const row of result.results) {
            const name: string = row.table_name || row.TABLE_NAME;
            // Session-keyed tables are supposed to outlive their creating run. Dropping one here
            // would delete the table a resume is about to adopt, and since this sweep is keyed on
            // the target, another session key's in-progress load into the same target too.
            if (isResumableStreamTable(name, table, prefix)) continue;
            if (!isAutosqlStreamTable(name, table, prefix)) continue;
            if (this.activeStreamStagingTables.has(name)) continue; // live stream on this instance — not an orphan
            this.db.warn(`autoSQLStream: dropping orphaned stream staging table '${name}' from a previous crashed run.`);
            const dropQ = buildDropStreamStagingTableQuery(name, config);
            await this.db.runTransaction([dropQ]).catch(e =>
                this.db.error(`Failed to drop orphaned stream staging table '${name}': ${e.message}`)
            );
        }
    }
}

import { AsyncLocalStorage } from 'async_hooks';
import { isValidSingleQuery } from './utils/validateQuery';
import type { QueryInput, DatabaseConfig, DialectConfig, AlterTableChanges, MetadataHeader, QueryResult, InsertInput } from '../config/types';
import { validateConfig, parseDatabaseMetaData } from '../helpers/utilities';
import { MAX_QUERY_ATTEMPTS } from "../config/defaults";
import type { AutoSQLHandler } from "./autosql";
import { setSSH } from '../helpers/ssh';

/**
 * Normalise a driver error's structured code for QueryResult.errorCode: non-empty string (mysql2
 * `code` / pg SQLSTATE) or number (SQL Server). Empty-string `code` → undefined; numeric `0` → "0".
 */
function driverErrorCode(err: any): string | undefined {
    const code = err?.code;
    return code != null && code !== "" ? String(code) : undefined;
}

export abstract class Database {
    protected connection: any | null = null;
    protected config: DatabaseConfig;
    public autoSQLHandler!: AutoSQLHandler;
    protected abstract getPermanentErrors(): Promise<string[]>;
    // Per-operation schema override: a schema-scoped call runs its whole async operation inside this
    // context so concurrent calls with different schemas stay isolated instead of racing on a shared,
    // mutated this.config.schema.
    private schemaContext = new AsyncLocalStorage<string>();
    // Per-operation number-format override. Separator consensus resolves ONE {thousands, decimal}
    // pair and runs the whole load inside this context, so inference, load-time sqlize and worker
    // dispatch all see it without mutating shared config. Isolated per-load like schemaContext.
    private separatorContext = new AsyncLocalStorage<{ thousands: string; decimal: string }>();

    constructor(config: DatabaseConfig) {
        this.config = validateConfig(config);
    }

    public getConfig() {
        const ctxSchema = this.schemaContext.getStore();
        const ctxSep = this.separatorContext.getStore();
        if (ctxSchema === undefined && ctxSep === undefined) return this.config;
        const cfg = { ...this.config };
        if (ctxSchema !== undefined) cfg.schema = ctxSchema;
        if (ctxSep !== undefined) {
            cfg.thousandsSeparator = ctxSep.thousands;
            cfg.decimalSeparator = ctxSep.decimal;
        }
        return cfg;
    }

    /**
     * Run `fn` with `schema` as the effective config schema for the whole async operation, without
     * mutating shared config, so concurrent operations on different schemas cannot interfere. A
     * falsy schema runs `fn` unchanged.
     */
    public runWithSchema<T>(schema: string | undefined, fn: () => T): T {
        if (!schema) return fn();
        return this.schemaContext.run(schema, fn);
    }

    /**
     * Run `fn` with resolved number-format separators as the effective config for the whole async
     * operation (including worker dispatch), without mutating shared config. A falsy pair runs `fn`
     * unchanged.
     */
    public runWithSeparators<T>(separators: { thousands: string; decimal: string } | undefined, fn: () => T): T {
        if (!separators) return fn();
        return this.separatorContext.run(separators, fn);
    }

    public updateTableMetadata(table: string, metaData: MetadataHeader, type: "metaData" | "existingMetaData" = "metaData"): void {
        if (!this.config[type]) {
            this.config[type] = {};
        }

        this.config[type][table] = {
            ...this.config[type][table],
            ...metaData
        };
    }

    public updateSchema(schema: string | undefined): void {
        this.config.schema = schema;
    }

    public log(msg: string): void { this.config.logger?.log?.(msg); }
    public warn(msg: string): void { this.config.logger?.warn?.(msg); }
    public error(msg: string): void { this.config.logger?.error?.(msg); }

    /**
     * Make blocked schema changes observable (R9). `deleteColumns`/`updatePrimaryKey` default to
     * false, so compareMetaData can compute a drop or PK change that is then silently not executed.
     * Warn once, naming the columns and the flag to flip. `primaryKeyChanges` is only populated on a
     * genuine delta and `dropColumns` is rename-folded, so neither warns on an unchanged re-ingest.
     */
    protected warnBlockedSchemaChanges(table: string, changes: AlterTableChanges): void {
        if (changes.dropColumns?.length && !this.config.deleteColumns) {
            this.warn(`Schema change not applied to '${table}': ${changes.dropColumns.length} column(s) would be dropped (${changes.dropColumns.join(", ")}) but 'deleteColumns' is off. Set deleteColumns: true to apply the drop, or leave it off to keep the columns.`);
        }
        if (changes.primaryKeyChanges?.length && !this.config.updatePrimaryKey) {
            this.warn(`Schema change not applied to '${table}': a primary-key change is pending (${changes.primaryKeyChanges.join(", ")}) but 'updatePrimaryKey' is off. Set updatePrimaryKey: true to apply it.`);
        }
        if (changes.noLongerUnique?.length && !this.config.dropUniqueConstraints) {
            this.warn(`Schema change not applied to '${table}': ${changes.noLongerUnique.length} column(s) (${changes.noLongerUnique.join(", ")}) now contain duplicate values that would require DROPPING their UNIQUE constraint, but 'dropUniqueConstraints' is off. The constraint is KEPT (the load may then fail on the duplicate rows); set dropUniqueConstraints: true to relax it.`);
        }
    }

    /**
     * Opt-in charset upgrade (R8): return DDL converting text columns whose charset differs from the
     * target. No-op in the base impl, because only MySQL has the 3-byte `utf8` vs 4-byte `utf8mb4`
     * split; Postgres `UTF8` already stores 4-byte chars.
     */
    public async getCharsetUpgradeQueries(_table: string): Promise<QueryInput[]> {
        return [];
    }

    static create(config: DatabaseConfig): Database {
        const dialects: Record<string, new (config: DatabaseConfig) => Database> = {
            mysql: MySQLDatabase,
            pgsql: PostgresDatabase,
            sqlserver: SqlServerDatabase
        };

        const dialect = config.sqlDialect?.toLowerCase();
        if (!dialects[dialect]) {
            throw new Error(`Unsupported SQL dialect: ${dialect}`);
        }

        return new dialects[dialect](config);
    }

    public getDialect() {
        return this.config.sqlDialect
    }

    public abstract getDialectConfig(): DialectConfig;

    public abstract establishDatabaseConnection(): Promise<void>;
    public abstract testQuery(queryOrParams: QueryInput): Promise<any>;
    // When `client` is provided the query runs on that pinned connection and the connection is
    // NOT released here (the transaction owner manages its lifecycle). Without a client, a
    // throwaway pool connection is acquired and released per call (standalone queries).
    protected abstract executeQuery(queryOrParams: QueryInput, client?: any): Promise<any>;
    // Acquire/release a single pooled connection so a transaction can run all of its
    // statements (START/…/COMMIT/ROLLBACK) on the same connection.
    protected abstract acquireConnection(): Promise<any>;
    protected abstract releaseConnection(client: any): void;
    // Discard a connection instead of returning it to the pool — used when a ROLLBACK failed, so the
    // next borrower isn't handed a connection stuck in an aborted-transaction state (A24).
    protected abstract destroyConnection(client: any): void;

    public async establishConnection(): Promise<void> {
        let attempts = 0;
        const maxAttempts = MAX_QUERY_ATTEMPTS || 3;

        while (attempts < maxAttempts) {
            try {
                if (this.config.sshConfig) {
                    const { stream, sshClient } = await setSSH(this.config.sshConfig, this.config.logger);
                    this.config.sshStream = stream;
                    this.config.sshClient = sshClient;
                }
                await this.establishDatabaseConnection();
                return;
            } catch (error: any) {
                this.error(`Database connection attempt ${attempts + 1} failed: ${error.message}`);

                // Close any SSH tunnel opened on this attempt so a retry/final-throw doesn't leak an
                // SSH connection per failed attempt.
                if (this.config.sshClient) {
                    try { this.config.sshClient.end(); } catch { /* already closed / never connected */ }
                    this.config.sshClient = undefined;
                    this.config.sshStream = undefined;
                }

                const permanentErrors = await this.getPermanentErrors();
                if (permanentErrors.includes(error.code)) {
                    this.error("Permanent error detected. Aborting retry.");
                    throw error;
                }

                attempts++;
                if (attempts < maxAttempts) {
                    await new Promise((res) => setTimeout(res, 1000)); // Wait 1 second before retrying
                }
            }
        }

        throw new Error("Database connection failed after multiple attempts.");
    }

    public async testConnection(): Promise<boolean> {
        try {
            const result = await this.runQuery({ query: "SELECT 1 AS solution;"});
            return !!result;
        } catch (error) {
            this.error(`Test connection failed: ${error}`);
            return false;
        }
    }

    public async checkSchemaExists(schemaName: string | string[]): Promise<Record<string, boolean>> {
        const query = this.getCheckSchemaQuery(schemaName);
        const result = await this.runQuery(query);

        // A failed query means we could NOT determine existence (connectivity/auth/permissions), not
        // that the schema is absent. Masking as `false` would mislead a caller into re-creating an
        // existing schema or skipping one that exists — surface the failure instead of guessing.
        if (!result.success) {
            throw new Error(`checkSchemaExists: could not determine schema existence — ${result.error}`);
        }

        const resultsArray = result.results ?? [];

        if (Array.isArray(schemaName)) {
            return schemaName.reduce((acc, db) => {
                acc[db] = resultsArray[0]?.[db] === 1;
                return acc;
            }, {} as Record<string, boolean>);
        }

        return { [schemaName]: resultsArray[0]?.[schemaName] === 1 };
    }

    /**
     * Create the schema if it doesn't exist. Resolves `{ [schemaName]: true }`, plus a deprecated
     * `success: true`. THROWS when the CREATE fails, with the driver code on `error.code`, so a
     * login without create rights surfaces the real cause rather than a later "schema not found".
     */
    public async createSchema(schemaName: string): Promise<Record<string, boolean>> {
        let result: QueryResult;
        try {
            result = await this.runQuery(this.getCreateSchemaQuery(schemaName));
        } catch (error) {
            throw new Error(`Failed to create schema "${schemaName}": ${error}`);
        }
        // runQuery reports a SQL error as success:false rather than throwing.
        if (!result.success) {
            const err: any = new Error(`Failed to create schema "${schemaName}": ${result.error ?? "unknown error"}${result.errorCode ? ` [${result.errorCode}]` : ""}`);
            if (result.errorCode) err.code = result.errorCode;
            throw err;
        }
        // `success` is kept for callers written against the old `{ success: true }` return (deprecated).
        return { [schemaName]: true, success: true };
    }

    public createTableQuery(table: string, headers: MetadataHeader): QueryInput[] {
        if (!table || !headers || Object.keys(headers).length === 0) {
            throw new Error("Invalid table configuration: table name and headers are required.");
        }
    
        return this.getCreateTableQuery(table, headers);
    }

    public async alterTableQuery(table: string, oldHeaders: MetadataHeader, newHeaders: MetadataHeader): Promise<QueryInput[]> {
        if (!table || !oldHeaders || !newHeaders) {
            throw new Error("Invalid table configuration: table name and headers are required.");
        }
    
        return this.getAlterTableQuery(table, oldHeaders, newHeaders);
    }

    public dropTableQuery(table: string): QueryInput {
        if (!table) {
            throw new Error("Invalid table configuration: table name is required.");
        }
    
        return this.getDropTableQuery(table);
    }
    

    // Transaction control statements. These require a pinned connection (see runTransaction);
    // a transaction spread across throwaway pool connections is not atomic. Call runTransaction
    // for atomic multi-statement work rather than these directly.
    public async startTransaction(client: any): Promise<void> {
        if (!client) throw new Error("startTransaction requires a pinned connection; use runTransaction() for atomic transactions.");
        await this.executeQuery("START TRANSACTION;", client);
    }

    public async commit(client: any): Promise<void> {
        if (!client) throw new Error("commit requires a pinned connection; use runTransaction().");
        await this.executeQuery("COMMIT;", client);
    }

    public async rollback(client: any): Promise<void> {
        if (!client) throw new Error("rollback requires a pinned connection; use runTransaction().");
        await this.executeQuery("ROLLBACK;", client);
    }

    public async closeConnection(): Promise<{ success: boolean; error?: string }> {
        if (!this.connection)  return { success: true };

        try {
            if ("end" in this.connection) {
                await this.connection.end(); // MySQL & PostgreSQL close method
            }
            if (this.config.sshClient) {
                this.config.sshClient.end();
            }
            return { success: true };
        } catch (error) {
            return { success: false, error: error instanceof Error ? error.message : "Unknown error" };
        } finally {
            this.connection = undefined;        
            this.config.sshClient = undefined;
            this.config.sshStream = undefined;
        }
    }
    
    public async runQuery(queryOrParams: QueryInput, maxAttemptsOverride?: number): Promise<QueryResult> {
        // `maxAttemptsOverride` lets a caller owning its OWN retry loop opt out of the internal retry.
        // Matters for NON-idempotent statements (single-row INSERT): on an ambiguous failure (conn
        // dropped AFTER the server applied the row) the internal retry would duplicate it.
        // `perRowInsertWithRetry` passes 1 for exactly this (A15).
        const maxAttempts = maxAttemptsOverride ?? MAX_QUERY_ATTEMPTS ?? 3;
        let attempts = 0;
        let _error: any;
        const start = new Date();
        let end: Date;

        const query: QueryInput = typeof queryOrParams === "string" ? { query: queryOrParams, params: [] } : queryOrParams;

        if (!isValidSingleQuery(query.query)) {
            return { start, end: new Date(), duration: 0, success: false, error: "Multiple SQL statements detected. Use transactions instead." };
        }

        while (attempts < maxAttempts) {
            try {
                const { rows, affectedRows } = await this.executeQuery(query);

                end = new Date();
                return {
                    start,
                    end,
                    duration: end.getTime() - start.getTime(),
                    affectedRows,
                    success: true,
                    results: rows
                };

            } catch (error: any) {
                const permanentErrors = await this.getPermanentErrors();
                if (permanentErrors.includes(error.code)) {
                    end = new Date();
                    return { start, end, duration: end.getTime() - start.getTime(), success: false, error: error.message, errorCode: driverErrorCode(error) };
                }
    
                attempts++;
                if (attempts < maxAttempts) {
                    await new Promise(res => setTimeout(res, 1000)); // Wait before retry
                } else {
                    _error = error;
                }
            }
        }
    
        end = new Date();
        return { start, end, duration: end.getTime() - start.getTime(), success: false, error: _error?.message, errorCode: driverErrorCode(_error) };
    }

    public async runTransaction(queriesOrStrings: QueryInput[]): Promise<QueryResult> {
        const start = new Date();
        // Establishing the connection can fail (bad creds, host down, SSH tunnel failure). Keep it
        // inside the failure envelope so runTransaction always resolves to a QueryResult and never
        // rejects (matches runQuery's contract) — a caller's process can't crash on a connect error.
        try {
            if (!this.connection) {
                await this.establishConnection();
            }
        } catch (error: any) {
            const end = new Date();
            return { start, end, duration: end.getTime() - start.getTime(), success: false, error: error instanceof Error ? error.message : String(error), errorCode: driverErrorCode(error) };
        }
        let end: Date;
        let _error: any;

        const queries = queriesOrStrings.map(query =>
            typeof query === "string" ? { query, params: [] } : query
        );

        // Retry the whole transaction, not individual statements: a deadlock or serialization failure
        // aborts the entire transaction, so a per-statement retry on the same connection cannot
        // succeed. A DDL-containing transaction runs exactly once, because MySQL implicitly commits
        // before each DDL and re-running would re-apply the already-committed DML.
        const containsDDL = queries.some(q => /^\s*(create|alter|drop|truncate|rename)\b/i.test(q.query || ""));
        const maxAttempts = containsDDL ? 1 : (MAX_QUERY_ATTEMPTS || 3);

        for (let attempt = 1; attempt <= maxAttempts; attempt++) {
            let client: any;
            let rollbackFailed = false;
            let results: any[] = [];
            let totalAffectedRows = 0;
            try {
                // Acquire INSIDE the try: pool exhaustion, an acquire timeout, or a connection
                // dropped between establish and acquire must become a {success:false} QueryResult
                // rather than an unhandled rejection, since callers rely on never-rejects (A16).
                client = await this.acquireConnection();
                await this.startTransaction(client);

                for (const query of queries) {
                    if (!query?.query?.trim()) continue; // Skip empty queries
                    const { rows, affectedRows } = await this.executeQuery(query, client);
                    results = results.concat(rows);
                    totalAffectedRows += affectedRows || 0;
                }

                await this.commit(client);
                end = new Date();
                return {
                    start,
                    end,
                    duration: end.getTime() - start.getTime(),
                    affectedRows: totalAffectedRows || results.length,
                    success: true,
                    results
                };
            } catch (error: any) {
                this.error(`Transaction error (attempt ${attempt}/${maxAttempts}): ${error}`);
                if (client) {
                    try {
                        await this.rollback(client);
                    } catch (rollbackError) {
                        rollbackFailed = true;
                        this.error(`Rollback failed: ${rollbackError}`);
                    }
                }

                const permanentErrors = await this.getPermanentErrors();
                if (permanentErrors.includes(error.code) || attempt >= maxAttempts) {
                    _error = error;
                    break;
                }
                await new Promise(res => setTimeout(res, 1000)); // Wait before retrying the whole transaction
            } finally {
                if (client) {
                    // A failed rollback leaves the connection dirty (esp. Postgres: aborted txn);
                    // destroy it rather than return a poisoned connection to the pool (A24).
                    if (rollbackFailed) this.destroyConnection(client);
                    else this.releaseConnection(client);
                }
            }
        }

        end = new Date();
        return {
            start,
            end,
            duration: end.getTime() - start.getTime(),
            success: false,
            error: _error?.message,
            errorCode: driverErrorCode(_error)
        };
    }

    public async runTransactionsWithConcurrency(queryGroups: QueryInput[][]): Promise<QueryResult[]> {
        // A connect failure must not reject the whole batch — return one failure result per group so
        // callers still get a well-formed array (matching the per-group failure path in runNext below).
        try {
            if (!this.connection) {
                await this.establishConnection();
            }
        } catch (error: any) {
            const now = new Date();
            const msg = error instanceof Error ? error.message : String(error);
            return queryGroups.map(() => ({ start: now, end: now, duration: 0, success: false, error: msg }));
        }
        const results: QueryResult[] = [];
        let running: Promise<void>[] = [];
        // Cap concurrency at the connections actually AVAILABLE — the pool size minus any connections
        // this instance has pinned for held schema locks (A25b). At least 1 so a batch always progresses.
        const poolSize = Math.max(1, this.getMaxConnections() - this.getHeldSchemaLockCount())

        let index = 0;
      
        const runNext = async () => {
          const i = index++;
          if (i >= queryGroups.length) return;
      
          this.log(`Running transaction for group #${i + 1}`);
          try {
            const result = await this.runTransaction(queryGroups[i]);
            results[i] = result;
          } catch (error: any) {
            results[i] = {
              start: new Date(),
              end: new Date(),
              duration: 0,
              success: false,
              error: error?.message || "Unknown error"
            };
          }
      
          await runNext();
        };
      
        for (let i = 0; i < Math.min(poolSize, queryGroups.length); i++) {
          running.push(runNext());
        }
      
        await Promise.all(running);
      
        return results;
    }

    public async getTableMetaData(schema: string, table: string): Promise<MetadataHeader | null> {
        try {
            if (!this.connection) throw new Error("Database connection not established.");
    
            const existsQueryInput = this.getTableExistsQuery(schema, table);
            const exists = await this.runQuery(existsQueryInput);
            // `exists` is always a (truthy) QueryResult, so the old `if (!exists)` never fired (A19).
            // Surface a failed existence probe, then read the COUNT(*) to short-circuit an absent table
            // (key casing varies by dialect, so read the first column value).
            if (!exists.success) {
                throw new Error(`Failed to check whether ${schema}.${table} exists: ${exists.error ?? "unknown error"}`);
            }
            const countRow = exists.results?.[0];
            const tableExists = countRow ? Number(Object.values(countRow)[0] ?? 0) > 0 : false;
            if (!tableExists) return null;

            const metaQuery = this.getTableMetaDataQuery(schema, table);
            const result = await this.runQuery(metaQuery);
            if (!result.success || !result.results) {
                throw new Error(`Failed to fetch metadata: ${result.error}`);
            }
    
            const parsedMetadata = parseDatabaseMetaData(result.results, this.getDialectConfig());
    
            if (!parsedMetadata) return null;
            if (typeof parsedMetadata === "object" && !Array.isArray(parsedMetadata)) {
                return parsedMetadata as MetadataHeader; // Single table case
            }
    
            throw new Error("Unexpected metadata format: Multiple tables returned for a single-table query.");
        } catch (error) {
            this.error(`Error fetching table metadata: ${error}`);
            return null;
        }
    }
    
    public abstract getCreateSchemaQuery(schemaName: string): QueryInput;
    public abstract getCheckSchemaQuery(schemaName: string | string[]): QueryInput;
    public abstract getCreateTableQuery(table: string, headers: MetadataHeader): QueryInput[]
    public abstract getAlterTableQuery(table: string, alterTableChangesOrOldHeaders: AlterTableChanges | MetadataHeader, newHeaders?: MetadataHeader): Promise<QueryInput[]>;
    public abstract getDropTableQuery(table: string): QueryInput;
    public abstract getPrimaryKeysQuery(table: string): QueryInput;
    public abstract getForeignKeyConstraintsQuery(table: string): QueryInput;
    public abstract getViewDependenciesQuery(table: string): QueryInput;
    public abstract getDropPrimaryKeyQuery(table: string): QueryInput;
    public abstract getDropUniqueConstraintQuery(table: string, indexName: string): QueryInput;
    public abstract getAddPrimaryKeyQuery(table: string, primaryKeys: string[]): QueryInput;
    public abstract getUniqueIndexesQuery(table: string, column_name?: string): QueryInput;
    public abstract getTableExistsQuery(schema: string, table: string): QueryInput;
    public abstract getTableMetaDataQuery(schema: string, table: string): QueryInput;
    public abstract getSplitTablesQuery(table: string): QueryInput;
    public abstract getInsertStatementQuery(tableOrInput: string | InsertInput, data?: Record<string, any>[], metaData?: MetadataHeader, insertType?: "UPDATE" | "INSERT"): QueryInput; 
    // `pkFilter` (optional) scopes the merge to a single primary key — used by the atomic staging
    // degradation path, which runs a per-PK merge in the same transaction as that PK's before-image.
    public abstract getInsertFromStagingQuery(tableOrInput: string | InsertInput, metaData?: MetadataHeader, insertType?: "UPDATE" | "INSERT", pkFilter?: Record<string, any>): QueryInput;
    // `pkFilter` (optional) scopes the before-image capture to a single primary key (same atomic path).
    public abstract getInsertChangedRowsToHistoryQuery(tableOrInput: string | InsertInput, metaData?: MetadataHeader, pkFilter?: Record<string, any>): QueryInput;
    public abstract getCreateTempTableQuery(table: string, stagingPrefix?: string): QueryInput;
    public abstract getConstraintConflictQuery(table: string, structure: { uniques: Record<string, string[]>; primary: string[] }, stagingPrefix?: string): QueryInput;

    public abstract getMaxConnections(): number;

    /**
     * How many schema locks this instance holds. Each pins a pool connection (mysql/pgsql) or a
     * transaction (sqlserver), so `runTransactionsWithConcurrency` subtracts them from the pool size
     * to avoid over-subscribing while locks are held (A25b).
     */
    protected getHeldSchemaLockCount(): number { return 0; }

    /**
     * The `ssl.rejectUnauthorized:false` warning and the `ssl`+`sshConfig` conflict warning were
     * copy-pasted verbatim across mysql.ts and pgsql.ts (and that drift was itself a bug once: SQL
     * Server's copy was missing the conflict warning, see PR #79 / the sshConfig refusal in
     * validateConfig). sqlserver.ts also calls this for its own rejectUnauthorized warning; its
     * `sshConfig` conflict branch is a no-op there in practice since `sshConfig`/`sshStream` on SQL
     * Server already throws in validateConfig before any connection code runs — this just means
     * every dialect goes through one copy of the message instead of three.
     */
    protected warnInsecureTlsAndTunnelConflict(ssl: unknown): void {
        if (ssl && typeof ssl === "object" && (ssl as { rejectUnauthorized?: boolean }).rejectUnauthorized === false) {
            this.config.logger?.warn?.("autosql: ssl.rejectUnauthorized is false — TLS certificate verification is DISABLED (use only for dev/self-signed).");
        }
        if (ssl && (this.config.sshConfig || this.config.sshStream)) {
            this.config.logger?.warn?.("autosql: both `ssl` and `sshConfig` are set — pick one encrypted path (direct TLS OR an SSH tunnel); TLS over an SSH stream is not a supported combination.");
        }
    }

    /**
     * acquireSchemaLock's "register the newly-acquired connection" step, identical across mysql.ts
     * and pgsql.ts: release whatever stale connection was already registered for this table (a
     * leftover entry would otherwise leak a pooled connection) before pointing the map at the new
     * one.
     */
    protected registerSchemaLockConnection<T extends { release(): void }>(connections: Map<string, T>, table: string, client: T): void {
        const stale = connections.get(table);
        if (stale && stale !== client) stale.release();
        connections.set(table, client);
    }

    /**
     * acquireSchemaLock's catch-path cleanup, identical across mysql.ts and pgsql.ts: if the map
     * was never updated to point at `client` (the lock wasn't acquired, or acquiring threw before
     * registration), release it — the one place that owns `client` at this point.
     */
    protected releaseSchemaLockConnectionOnError<T extends { release(): void }>(connections: Map<string, T>, table: string, client: T | undefined): void {
        if (client && connections.get(table) !== client) client.release();
    }

    /**
     * Bulk-load already-sqlized value rows using the dialect's native mechanism. `columns` is the
     * ordered list each row's values align to. Throws on failure so the caller can fall back to
     * parameterised INSERT.
     */
    public abstract bulkLoadRows(table: string, columns: string[], rows: any[][], header?: MetadataHeader): Promise<QueryResult>;

    /**
     * Acquire a database-native advisory lock scoped to the given table (MySQL `GET_LOCK` on a
     * dedicated pool connection, Postgres `pg_try_advisory_lock` on a dedicated client). Held until
     * `releaseSchemaLock`.
     */
    public abstract acquireSchemaLock(table: string, timeoutSeconds: number): Promise<void>;

    /** Release the lock from `acquireSchemaLock`. Safe to call when none is held. */
    public abstract releaseSchemaLock(table: string): Promise<void>;

    get autoSQL() {
        return this.autoSQLHandler.autoSQL.bind(this.autoSQLHandler);
    }

    // Dry run: what an autoSQL(table, data, …) call WOULD do (schema diff + DDL), computed without
    // writing. See AutoSQLHandler.preview.
    get preview() {
        return this.autoSQLHandler.preview.bind(this.autoSQLHandler);
    }

    get autoCreateTable() {
        return this.autoSQLHandler.autoCreateTable.bind(this.autoSQLHandler);
    }

    get autoAlterTable() {
        return this.autoSQLHandler.autoAlterTable.bind(this.autoSQLHandler);
    }

    get fetchTableMetadata() {
        return this.autoSQLHandler.fetchTableMetadata.bind(this.autoSQLHandler);
    }

    get splitTableData() {
        return this.autoSQLHandler.splitTableData.bind(this.autoSQLHandler);
    }

    get autoInsertData() {
        return this.autoSQLHandler.autoInsertData.bind(this.autoSQLHandler);
    }

    get handleMetadata() {
        return this.autoSQLHandler.handleMetadata.bind(this.autoSQLHandler);
    }

    get autoConfigureTable() {
        return this.autoSQLHandler.autoConfigureTable.bind(this.autoSQLHandler);
    }

    get autoSQLChunked() {
        return this.autoSQLHandler.autoSQLChunked.bind(this.autoSQLHandler);
    }

    get openStream() {
        return this.autoSQLHandler.openStream.bind(this.autoSQLHandler);
    }
}

import { MySQLDatabase } from "./mysql";
import { PostgresDatabase } from "./pgsql";
import { SqlServerDatabase } from "./sqlserver";

export { MySQLDatabase, PostgresDatabase, SqlServerDatabase };

import type { AutoSQLHandler } from "./autosql";
import type { Database } from "./database";
import type { InsertInput, QueryResult, MetadataHeader, QueryInput } from "../config/types";
import { getInsertValues, tableChangesExist, throwIfFailedResults, sqlize } from "../helpers/utilities";
import { getMetaData, compareMetaData, restrictInferredUniques } from "../helpers/metadata";
import { buildBootstrapRejectedRowsQuery, buildInsertRejectedRowsQuery } from "../helpers/streamHelpers";
import { DEFAULTS } from "../config/defaults";

/**
 * Graceful-degradation collaborator: the shared per-row retry engine plus the direct-insert,
 * staging non-atomic, and staging atomic-per-PK adapters. Holds a back-ref to the handler because
 * schema widening is worker-dispatched (configureTables).
 */
export class DegradationPolicy {
    private handler: AutoSQLHandler;
    private db: Database;

    constructor(handler: AutoSQLHandler, db: Database) {
        this.handler = handler;
        this.db = db;
    }

    /**
     * Per-row fallback for the direct-insert path: retry each row of a failed batch, widening the
     * schema between rounds, and divert still-failing rows to `rejectedRowsTable`. The failed batch
     * ran as a transaction and rolled back, so re-inserting every row cannot double-insert.
     */
    async applyPerRowFallback(insertInput: InsertInput[], allInsertResults: QueryResult[]): Promise<QueryResult[]> {
        const config = this.db.getConfig();
        const maxRetries = config.streamMaxRetries ?? DEFAULTS.streamMaxRetries;
        for (let i = 0; i < allInsertResults.length; i++) {
            if (allInsertResults[i]?.success) continue;
            const input = insertInput[i];
            if (!input?.data?.length || !input.metaData) {
                // Nothing to retry per-row (no rows/metadata) — surface the original failure.
                throwIfFailedResults([allInsertResults[i]], "data insert queries");
                continue;
            }
            const insertType = input.insertType ?? config.insertType ?? 'UPDATE';
            // Preserve already-resolved key columns during widening re-inference so it can't re-infer
            // different keys for the failed rows.
            const primaryKey = Object.keys(input.metaData).filter(col => input.metaData[col]?.primary);
            this.db.warn(`autoSQL: batch insert for '${input.table}' failed (${allInsertResults[i]?.error ?? 'unknown error'}); retrying per-row with schema widening, diverting unrecoverable rows to '${config.rejectedRowsTable}'.`);
            const { inserted } = await this.perRowInsertWithRetry(
                input.table, input.data, input.metaData, insertType, maxRetries,
                primaryKey.length ? primaryKey : undefined
            );
            allInsertResults[i] = { ...allInsertResults[i], success: true, affectedRows: inserted, error: undefined };
        }
        return allInsertResults;
    }

    /**
     * Insert `rows` one at a time after a bulk insert failed, widening the table between rounds to
     * fit whatever failed (up to `maxRetries`). Rows still failing divert to `rejectedRowsTable`, or
     * this throws. Shared by the streaming end() flush and the direct-insert path.
     */
    async perRowInsertWithRetry(
        table: string,
        rows: Record<string, any>[],
        metaData: MetadataHeader,
        insertType: 'UPDATE' | 'INSERT',
        maxRetries: number,
        primaryKey?: string[],
        label: string = 'autoSQL'
    ): Promise<{ inserted: number; rejected: Record<string, any>[] }> {
        const config = this.db.getConfig();
        let pendingRows = rows;
        let workingMeta = metaData;
        let totalInserted = 0;
        let round = 0;

        while (pendingRows.length > 0 && round < maxRetries) {
            round++;
            const failures: { row: Record<string, any>; error: string }[] = [];

            for (const row of pendingRows) {
                // Pre-sqlize like the bulk path so this fallback normalizes values (separators,
                // decimal rounding, timezone, booleans) instead of binding raw. Without it a
                // locale-formatted number could never land via degradation or streaming.
                const normalisedRow = getInsertValues(workingMeta, row, this.db.getDialectConfig(), this.db.getConfig(), true);
                const insertQ = this.db.getInsertStatementQuery(table, [normalisedRow], workingMeta, insertType);
                // Single attempt: this loop already retries across rounds, so the internal retry is
                // redundant — and for "INSERT" (non-idempotent) could duplicate a row whose ambiguous
                // failure actually applied server-side (A15).
                const result = await this.db.runQuery(insertQ, 1);
                if (result.success) {
                    totalInserted += result.affectedRows ?? 1;
                } else {
                    failures.push({ row, error: result.error ?? 'unknown error' });
                }
            }

            // Remaining work = only rows that failed this round. Assign BEFORE the break so a fully
            // successful round leaves nothing pending — otherwise inserted rows would stay in
            // pendingRows and get diverted as "rejects" below.
            pendingRows = failures.map(f => f.row);
            if (pendingRows.length === 0) break;

            if (round < maxRetries) {
                // Widen the schema to fit the rows that failed, then loop retries only those rows.
                const failedMeta = restrictInferredUniques(await getMetaData(config, pendingRows, primaryKey), workingMeta, config);
                const { changes, updatedMetaData } = compareMetaData(workingMeta, failedMeta, this.db.getDialectConfig(), config.logger);
                if (tableChangesExist(changes)) {
                    const widenInput = [{
                        table,
                        data: pendingRows,
                        metaData: updatedMetaData,
                        previousMetaData: workingMeta,
                        comparedMetaData: { changes, updatedMetaData },
                        stagingPrefix: config.stagingPrefix,
                        historyTableSuffix: config.historyTableSuffix,
                    }];
                    await this.handler['configureTables'](widenInput).catch(e =>
                        this.db.warn(`${label}: schema widening attempt failed: ${e.message}`)
                    );
                    workingMeta = updatedMetaData;
                }
            }
        }

        if (pendingRows.length > 0) {
            if (config.rejectedRowsTable) {
                const bootstrap = await this.db.runTransaction(buildBootstrapRejectedRowsQuery(config));
                const rejQ = buildInsertRejectedRowsQuery(
                    config, table,
                    pendingRows.map(row => ({ row, error: 'failed after max retries' }))
                );
                // Fail loud if the divert itself fails (bootstrap or insert). runTransaction returns
                // {success:false} rather than throwing, so an unchecked result would let rows vanish
                // while the load reported success — the exact loss rejectedRowsTable prevents (A5).
                const divert = bootstrap.success ? await this.db.runTransaction([rejQ]) : bootstrap;
                if (!divert.success) {
                    throw new Error(`${label}: ${pendingRows.length} row(s) failed to insert AND could not be written to rejectedRowsTable '${config.rejectedRowsTable}': ${divert.error ?? 'unknown error'}. No rows were silently dropped — resolve the rejects-table error (e.g. permissions or an incompatible existing table) and retry.`);
                }
                this.db.warn(`${label}: ${pendingRows.length} row(s) could not be inserted and were written to '${config.rejectedRowsTable}'.`);
            } else {
                throw new Error(`${label}: ${pendingRows.length} row(s) failed to insert after ${maxRetries} retry round(s). Configure rejectedRowsTable to capture them instead of throwing.`);
            }
        }

        // `rejected` is the set of rows diverted to rejectedRowsTable (empty when all rows landed).
        // The staging path uses it to compensate row-level history for rows that never merged.
        return { inserted: totalInserted, rejected: pendingRows };
    }

    /**
     * Per-row fallback for the STAGING path without row-level history. The atomic merge rolled back,
     * so nothing from the failed table landed; re-run its rows as upserts to match merge semantics.
     */
    async applyStagingPerRowFallback(insertInput: InsertInput[], allInsertResults: QueryResult[]): Promise<QueryResult[]> {
        const config = this.db.getConfig();
        const maxRetries = config.streamMaxRetries ?? DEFAULTS.streamMaxRetries;
        for (let i = 0; i < allInsertResults.length; i++) {
            if (allInsertResults[i]?.success) continue;
            const input = insertInput[i];
            if (!input?.data?.length || !input.metaData) {
                // Nothing to retry per-row — surface the original failure.
                throwIfFailedResults([allInsertResults[i]], 'insert from staging table queries');
                continue;
            }
            const primaryKey = Object.keys(input.metaData).filter(col => input.metaData[col]?.primary);
            this.db.warn(`autoSQL: staged merge for '${input.table}' failed (${allInsertResults[i]?.error ?? 'unknown error'}); retrying per-row, diverting unrecoverable rows to '${config.rejectedRowsTable}'.`);
            const { inserted } = await this.perRowInsertWithRetry(
                input.table, input.data, input.metaData, 'UPDATE', maxRetries,
                primaryKey.length ? primaryKey : undefined
            );
            allInsertResults[i] = { ...allInsertResults[i], success: true, affectedRows: inserted, error: undefined };
        }
        return allInsertResults;
    }

    /**
     * Per-PK fallback for the atomic history path: [before-image, single-PK merge] in ONE
     * transaction, so a PK whose merge violates a constraint rolls back with no history and no data.
     * No widening here, because `configureTables` already fitted the schema to every row, so a
     * failure is a data problem re-inference cannot fix.
     */
    async perPkAtomicStagingMerge(input: InsertInput, stagingInput: InsertInput, historyInput?: InsertInput): Promise<QueryResult> {
        const config = this.db.getConfig();
        const dialectConfig = this.db.getDialectConfig();
        const header = input.comparedMetaData?.updatedMetaData || input.metaData;
        const pkCols = Object.keys(header).filter(col => header[col]?.primary);
        if (!pkCols.length) {
            throw new Error(`autoSQL: staged merge for '${input.table}' failed and cannot degrade per-row (no primary key to divert on).`);
        }
        this.db.warn(`autoSQL: staged merge for '${input.table}' failed; retrying per-row atomically (before-image + merge in one transaction), diverting unrecoverable rows to '${config.rejectedRowsTable}'.`);

        let inserted = 0;
        const rejected: Record<string, any>[] = [];
        for (const row of input.data) {
            const pkFilter: Record<string, any> = {};
            for (const pk of pkCols) pkFilter[pk] = sqlize(row[pk], header[pk].type, dialectConfig, config);
            const group: QueryInput[] = [];
            if (historyInput) group.push(this.db.getInsertChangedRowsToHistoryQuery(historyInput, undefined, pkFilter));
            group.push(this.db.getInsertFromStagingQuery(stagingInput, undefined, undefined, pkFilter));
            const result = await this.db.runTransaction(group);
            if (result.success) inserted += 1; // one data row per PK landed (history rows aren't counted)
            else rejected.push(row);
        }

        if (rejected.length) {
            if (!config.rejectedRowsTable) {
                throw new Error(`autoSQL: ${rejected.length} row(s) failed to merge into '${input.table}' and rejectedRowsTable is not configured.`);
            }
            const bootstrap = await this.db.runTransaction(buildBootstrapRejectedRowsQuery(config));
            const divert = bootstrap.success
                ? await this.db.runTransaction([
                    buildInsertRejectedRowsQuery(config, input.table, rejected.map(row => ({ row, error: 'failed to merge after per-row retry' })))
                  ])
                : bootstrap;
            // Fail loud if the divert itself fails — otherwise rows vanish while the load reports
            // success (A5). runTransaction returns {success:false} rather than throwing, so check it.
            if (!divert.success) {
                throw new Error(`autoSQL: ${rejected.length} row(s) failed to merge into '${input.table}' AND could not be written to rejectedRowsTable '${config.rejectedRowsTable}': ${divert.error ?? 'unknown error'}. No rows were silently dropped — resolve the rejects-table error (e.g. permissions or an incompatible existing table) and retry.`);
            }
            this.db.warn(`autoSQL: ${rejected.length} row(s) could not be merged into '${input.table}' and were written to '${config.rejectedRowsTable}'.`);
        }
        const now = new Date();
        return { start: now, end: now, duration: 0, success: true, affectedRows: inserted };
    }
}

import type { AutoSQLHandler } from "./autosql";
import type { Database } from "./database";
import type { InsertInput, MetadataHeader, QueryResult, AlterTableChanges } from "../config/types";
import { getHistoryTableName, throwIfFailedResults } from "../helpers/utilities";
import {
    bootstrapSchemaHistoryTable,
    recordMigrationStart,
    recordMigrationSuccess,
    recordMigrationRolledBack,
    recordMigrationFailed,
    detectSchemaDrift,
} from "../helpers/schemaHistory";

/**
 * Row-level history collaborator: builds the per-table history inputs and populates the history
 * tables. Holds a back-ref to the handler because table configuration is worker-dispatched.
 */
export class HistoryCoordinator {
    private handler: AutoSQLHandler;
    private db: Database;

    constructor(handler: AutoSQLHandler, db: Database) {
        this.handler = handler;
        this.db = db;
    }

    private async insertToHistoryTables(insertInputs: InsertInput[]): Promise<QueryResult[]> {
        const stagingInsertQueries = (insertInputs).map(insertInput => {
            return [this.db.getInsertChangedRowsToHistoryQuery(insertInput)]
        })
        const allInsertResults : QueryResult[] = await this.db.runTransactionsWithConcurrency(stagingInsertQueries);
        throwIfFailedResults(allInsertResults, 'insert from staging table queries')
        return allInsertResults
    }

    /**
     * Build the per-table history inputs (cleaned metadata + `dwh_as_at` PK). Shared by the atomic
     * and non-atomic paths. Returns [] when history is off or no eligible table is present.
     */
    private async buildHistoryInputs(insertInput: InsertInput[]): Promise<InsertInput[]> {
        const config = this.db.getConfig();
        if (!config.addHistory || !config.historyTables?.length) return [];
        if (!config.useStagingInsert) { throw new Error('Cannot add history tables without using staging insert'); }

        const uniqueTables = Array.from(new Set(insertInput.map(input => input.table)));
        const eligibleInputs = uniqueTables.filter(table => config.historyTables!.includes(table));
        if (eligibleInputs.length == 0) { return []; }

        return Promise.all(
            eligibleInputs.map(async (table) => {
              const matchingInput = insertInput.find(i => i.table === table);
              const historyName = getHistoryTableName(table, matchingInput?.historyTableSuffix);

              const [currentStatus, historyStatus] = await Promise.all([
                this.handler.fetchTableMetadata(table),
                this.handler.fetchTableMetadata(historyName),
              ]);

              const currentMetaData = currentStatus.currentMetaData;
              const currentHistoryMetaData = historyStatus.currentMetaData;

              if (!currentMetaData) {
                throw new Error(`Could not find structure of ${table} for history table creation`);
              }

              const cleanedMeta: MetadataHeader = {};
              for (const col in currentMetaData) {
                const def = { ...currentMetaData[col] };
                def.unique = false;
                def.index = false
                cleanedMeta[col] = def;
              }

              cleanedMeta["dwh_as_at"] = { type: "datetime", allowNull: false, primary: true };

              const automatedColumns = ['dwh_created_at', 'dwh_modified_at', 'dwh_loaded_at']
              // Ensure existing PKs are retained
              for (const col in currentMetaData) {
                if (currentMetaData[col].primary) { cleanedMeta[col].primary = true; }
                if (automatedColumns.includes(col)) { cleanedMeta[col].calculated = true }
              }

              return {
                table: historyName,
                data: [],
                metaData: cleanedMeta,
                previousMetaData: currentHistoryMetaData,
                // Carry the prefix/suffix so the history/temp/real table names resolve correctly (incl.
                // custom prefixes) both in the before-image query and in the atomic path's table map.
                stagingPrefix: matchingInput?.stagingPrefix,
                historyTableSuffix: matchingInput?.historyTableSuffix,
              };
            })
        );
    }

    async insertHistory(insertInput: InsertInput[]): Promise<QueryResult[]> {
        const historyInputs = await this.buildHistoryInputs(insertInput);
        if (!historyInputs.length) return [];
        await this.handler['configureTables'](historyInputs)
        return this.insertToHistoryTables(historyInputs)
    }

    /**
     * Create the history tables (DDL only) for the ATOMIC path; the before-image INSERT itself is
     * deferred into the merge transaction (see `insertFromStagingTablesAtomic`).
     */
    async configureHistoryTables(insertInput: InsertInput[]): Promise<InsertInput[]> {
        const historyInputs = await this.buildHistoryInputs(insertInput);
        if (!historyInputs.length) return [];
        await this.handler['configureTables'](historyInputs);
        return historyInputs;
    }

    // --- Schema-history / drift (thin wrappers over helpers/schemaHistory) ---

    async detectDrift(table: string): Promise<void> {
        await detectSchemaDrift(this.db, table);
    }

    async bootstrap(): Promise<void> {
        await bootstrapSchemaHistoryTable(this.db);
    }

    async recordStart(table: string, previousSchema: MetadataHeader, changes: AlterTableChanges): Promise<number | undefined> {
        return recordMigrationStart(this.db, table, previousSchema, changes);
    }

    async recordSuccess(historyId: number, newSchema: MetadataHeader, checksumSchema?: MetadataHeader | null): Promise<void> {
        await recordMigrationSuccess(this.db, historyId, newSchema, checksumSchema);
    }

    async recordRolledBack(historyId: number): Promise<void> {
        await recordMigrationRolledBack(this.db, historyId);
    }

    async recordFailed(historyId: number): Promise<void> {
        await recordMigrationFailed(this.db, historyId);
    }
}

import type { AutoSQLHandler } from "./autosql";
import type { Database } from "./database";
import type { StagingPipeline } from "./stagingPipeline";
import type { HistoryCoordinator } from "./historyCoordinator";
import type { InsertInput, QueryResult } from "../config/types";

/**
 * Prepared inputs handed to a LoadStrategy: metadata resolved, split applied, nested appended, and
 * tables already configured. `table`/`label` are only for the staging-cleanup error message.
 */
export interface LoadContext {
    insertInput: InsertInput[];
    table: string;
    label: string;
}

export interface LoadStrategy {
    /**
     * Load already-configured inputs and return one QueryResult per input. Implementations own
     * staging-vs-direct dispatch, conflict resolution, row-level history, and graceful degradation.
     * Runs inside the caller's runWithSchema/runWithSeparators scope.
     */
    load(ctx: LoadContext): Promise<QueryResult[]>;
}

/**
 * The default row-store load strategy. The LoadStrategy seam exists so a future columnar
 * `StageCopyLoad` can implement the same contract (R1 Slice 2).
 */
export class RowStoreLoadStrategy implements LoadStrategy {
    constructor(
        private handler: AutoSQLHandler,
        private db: Database,
        private staging: StagingPipeline,
        private history: HistoryCoordinator,
    ) {}

    async load(ctx: LoadContext): Promise<QueryResult[]> {
        const config = this.db.getConfig();
        const input = ctx.insertInput;
        if (config.useStagingInsert) {
            // Row-level history takes the atomic path (before-image + merge in ONE transaction) so
            // history and data commit or roll back together, leaving no crash window between them.
            // rejectedRowsTable forces this branch too, since it needs addHistory for before-images;
            // only the merge-failure handling differs (see perRowFallback below).
            const useAtomicHistory = !!(config.addHistory && config.historyTables?.length);
            try {
                await this.staging.prepareStagingTables(input);
                await this.staging.insertStagingTables(input);
                await this.staging.resolveConflicts(input);
                if (useAtomicHistory) {
                    const historyInputs = await this.history.configureHistoryTables(input);
                    return await this.staging.insertFromStagingTablesAtomic(input, historyInputs, { perRowFallback: !!config.rejectedRowsTable });
                } else {
                    await this.history.insertHistory(input);
                    return await this.staging.insertFromStagingTables(input, { perRowFallback: !!config.rejectedRowsTable });
                }
            } finally {
                // Drop staging even if a step above threw, so a failed load leaves no orphaned temp
                // table (mirrors the streaming end() path).
                await this.staging.removeStagingTables(input).catch(e => this.db.error(`${ctx.label}: failed to drop staging table(s) for '${ctx.table}': ${e instanceof Error ? e.message : String(e)}`));
            }
        } else {
            return this.handler['insertData'](input, { perRowFallback: true });
        }
    }
}

import crypto from "crypto";
import { Readable } from "stream";
import type { ResultSetHeader, FieldPacket, PoolConnection, Pool } from "mysql2/promise";
import { Database } from "./database";
import { MYSQL_PERMANENT_ERRORS } from './permanentErrors/mysql';
import type { QueryInput, DatabaseConfig, AlterTableChanges, MetadataHeader, InsertInput, QueryResult } from "../config/types";
import { normalizeResultKeys, isMetadataHeader } from "../helpers/utilities";
import { serializeRowsToCopyText } from "../helpers/bulkLoad";
import { MYSQL_CONFIG } from "./config/mysqlConfig";
import { isValidSingleQuery } from './utils/validateQuery';
import { escapeIdentifier, escapeLiteral } from './utils/escape';
import { compareMetaData } from '../helpers/metadata';
import { MySQLTableQueryBuilder } from "./queryBuilders/mysql/tableBuilder";
import { MySQLIndexQueryBuilder } from "./queryBuilders/mysql/indexBuilder";
import { MySQLInsertQueryBuilder } from "./queryBuilders/mysql/insertBuilder";
import { AutoSQLHandler } from "./autosql";
import { SchemaLockTimeoutError } from "../errors";
const DIALECT_CONFIG = MYSQL_CONFIG

export class MySQLDatabase extends Database {
    private schemaLockConnections: Map<string, PoolConnection> = new Map();

    constructor(config: DatabaseConfig) {
        super(config);
        this.autoSQLHandler = new AutoSQLHandler(this);
    }

    async establishDatabaseConnection(): Promise<void> {
        let mysql: any;
        try {
            // Lazy require, not a static import: mysql2 is an OPTIONAL peer dependency — a static
            // import would force every consumer to install all three drivers.
            // eslint-disable-next-line @typescript-eslint/no-require-imports
            mysql = require("mysql2/promise");
        } catch {
            throw new Error("Missing required dependency 'mysql2'. Please install it to use MySQLDatabase.");
        }
        // TLS passthrough. mysql2 rejects `ssl: true` (wants an object/named profile), so normalise
        // `true` → `{}` (enable TLS, default verification); an object is passed as-is.
        const ssl = this.config.ssl;
        this.warnInsecureTlsAndTunnelConflict(ssl);
        this.connection = mysql.createPool({
            host: this.config.host,
            user: this.config.user,
            password: this.config.password,
            database: this.config.database || this.config.schema,
            port: this.config.port || 3306,
            connectionLimit: this.config.connectionLimit || 5,
            // Pin the connection charset to a 4-byte-capable encoding. Without this mysql2 negotiates
            // its default (historically 3-byte utf8_general_ci), so a 4-byte char (emoji, some CJK)
            // throws `Incorrect string value` on INSERT even when the table is utf8mb4.
            charset: this.config.charset || DIALECT_CONFIG.charset,
            // `ssl: false` == omitting it (plaintext/driver default); only truthy `ssl` is threaded.
            // mysql2 rejects `ssl: true`, so normalise it to `{}`.
            ...(ssl ? { ssl: ssl === true ? {} : ssl } : {}),
            ...(this.config.sshStream ? { stream: this.config.sshStream } : {})
        });
    }

    /**
     * Stable, ≤64-char key for MySQL's `GET_LOCK`/`RELEASE_LOCK` (per-table advisory lock).
     * `autosql_schema__` prefix + a long table name can exceed MySQL's 64-char lock-name limit, making
     * `GET_LOCK` fail obscurely — so a too-long key is deterministically hash-truncated (same table →
     * same key, so lock/release still match). NOTE: a truncated key differs from the raw form, so two
     * processes on different autosql versions would not mutually exclude on it (see decisions.md).
     */
    private static schemaLockKey(table: string): string {
        const prefix = "autosql_schema__"; // 16 chars
        const key = `${prefix}${table}`;
        // Measure/truncate by Unicode CODE POINTS (MySQL counts characters) on character boundaries so
        // truncation can't split a surrogate pair.
        if ([...key].length <= 64) return key;
        const hash = crypto.createHash("md5").update(key).digest("hex").slice(0, 8);
        const budget = 64 - prefix.length - 1 - hash.length; // 39 code points
        const truncated = [...table].slice(0, budget).join("");
        return `${prefix}${truncated}_${hash}`;
    }

    public getMaxConnections(): number {
        // mysql2's promise wrapper keeps the pool config on the underlying `.pool` (not `.config`).
        const conn = this.connection;
        return conn?.pool?.config?.connectionLimit ?? conn?.config?.connectionLimit ?? 5;
    }

    protected getHeldSchemaLockCount(): number { return this.schemaLockConnections.size; }

    public async bulkLoadRows(table: string, columns: string[], rows: any[][]): Promise<QueryResult> {
        const start = new Date();
        if (!this.connection) await this.establishConnection();
        if (rows.length === 0) {
            return { start, end: new Date(), duration: 0, success: true, affectedRows: 0 };
        }
        const schema = this.getConfig().schema;
        const schemaPrefix = schema ? `${escapeIdentifier(schema, "mysql")}.` : "";
        const colList = columns.map(c => escapeIdentifier(c, "mysql")).join(", ");
        const body = serializeRowsToCopyText(rows);
        const client = await (this.connection as Pool).getConnection();
        try {
            // The stream body matches serializeRowsToCopyText: TAB fields, newline rows, `\` escape,
            // `\N` NULL. CHARACTER SET utf8mb4 so 4-byte characters load intact.
            const sql =
                `LOAD DATA LOCAL INFILE 'autosql-bulk' INTO TABLE ${schemaPrefix}${escapeIdentifier(table, "mysql")} ` +
                `CHARACTER SET utf8mb4 FIELDS TERMINATED BY '\\t' ESCAPED BY '\\\\' LINES TERMINATED BY '\\n' (${colList})`;
            // mysql2 streams the infile as Buffers (it calls Buffer.copy), so yield a Buffer.
            await client.query({ sql, infileStreamFactory: () => Readable.from([Buffer.from(body, "utf8")]) } as any);
            const end = new Date();
            return { start, end, duration: end.getTime() - start.getTime(), success: true, affectedRows: rows.length };
        } finally {
            client.release();
        }
    }

    public async acquireSchemaLock(table: string, timeoutSeconds: number): Promise<void> {
        const lockKey = MySQLDatabase.schemaLockKey(table);
        if (!this.connection) await this.establishConnection();
        let client: PoolConnection | undefined;
        try {
            client = await (this.connection as Pool).getConnection();
            const [rows] = await client.query('SELECT GET_LOCK(?, ?) AS acquired', [lockKey, timeoutSeconds]) as [any[], any];
            const acquired = rows[0]?.acquired;
            if (!acquired) {
                // Don't release here — the catch below releases exactly once (map not set for this
                // table, so its guard fires); releasing here too would double-release on timeout.
                throw new SchemaLockTimeoutError(
                    `Could not acquire schema lock for table '${table}' within ${timeoutSeconds}s. ` +
                    `Another process may be modifying this table's schema. Increase schemaLockTimeout or retry later.`
                );
            }
            this.registerSchemaLockConnection(this.schemaLockConnections, table, client);
        } catch (error) {
            this.releaseSchemaLockConnectionOnError(this.schemaLockConnections, table, client);
            throw error;
        }
    }

    public async releaseSchemaLock(table: string): Promise<void> {
        const lockKey = MySQLDatabase.schemaLockKey(table);
        const client = this.schemaLockConnections.get(table);
        if (!client) return;
        // Drop the registration before awaiting so a concurrent acquire/release can't observe a
        // half-torn-down entry.
        this.schemaLockConnections.delete(table);
        try {
            await client.query('SELECT RELEASE_LOCK(?)', [lockKey]);
            client.release();
        } catch (error) {
            // RELEASE_LOCK failed: the lock may still be held on this connection, so returning it to
            // the pool would hand the next caller a lock-holding connection. Destroy it instead —
            // MySQL releases session locks on connection close, and the pool replaces it. Releasing a
            // lock is cleanup, so a failure here is logged, not thrown.
            this.warn(`releaseSchemaLock: failed to release schema lock for '${table}'; destroying the connection so a lock-holding connection is not returned to the pool — ${error instanceof Error ? error.message : String(error)}`);
            try { client.destroy(); } catch { /* connection already broken */ }
        }
    }

    public getDialectConfig() {
        return DIALECT_CONFIG;
    }

    protected async getPermanentErrors(): Promise<string[]> {
        return MYSQL_PERMANENT_ERRORS;
    }

    async testQuery(queryOrParams: QueryInput): Promise<any> {

        const query = typeof queryOrParams === "string" ? queryOrParams : queryOrParams.query;
    
        if (!isValidSingleQuery(query)) {
            throw new Error("Each query in the transaction must be a single statement.");
        }
    
        if (!this.connection) {
            await this.establishConnection();
        }

        let client: PoolConnection | null = null;
        try {
            client = await (this.connection as Pool).getConnection();
    
            // Use PREPARE to validate syntax without executing
            await client.query(`PREPARE stmt FROM ?`, [query]);
            await client.query(`DEALLOCATE PREPARE stmt`); // Cleanup
    
            return { success: true };
        } catch (error: any) {
            if(client) await client.query("ROLLBACK;");
            this.error(`MySQL testQuery failed: ${error}`);
            throw error;
        } finally {
            if (client) client.release();
        }
    }

    protected async acquireConnection(): Promise<PoolConnection> {
        if (!this.connection) {
            await this.establishConnection();
        }
        return (this.connection as Pool).getConnection();
    }

    protected releaseConnection(client: PoolConnection): void {
        if (client) client.release();
    }

    protected destroyConnection(client: PoolConnection): void {
        // Discard rather than return to the pool (A24) — after a failed rollback the connection may be dirty.
        if (client) { try { client.destroy(); } catch { /* already broken */ } }
    }

    protected async executeQuery(query: string, client?: PoolConnection): Promise<any>;
    protected async executeQuery(QueryInput: QueryInput, client?: PoolConnection): Promise<any>;
    protected async executeQuery(queryOrParams: QueryInput, client?: PoolConnection): Promise<{ rows: any[]; affectedRows: number }> {
        if (!this.connection) {
            await this.establishConnection();
        }

        const pinned = !!client;
        let conn: PoolConnection | null = client ?? null;
        const query = typeof queryOrParams === "string" ? queryOrParams : queryOrParams.query;
        const params = typeof queryOrParams === "string" ? [] : queryOrParams.params || [];

        try {
            if (!conn) conn = await (this.connection as Pool).getConnection();
            const [rowsOrResult, maybeHeader] = await conn.query(query, params) as [any, ResultSetHeader | FieldPacket[]];

            const rows = Array.isArray(rowsOrResult) ? rowsOrResult : [];
            let affectedRows = 0;

            // For INSERT/UPDATE/DELETE, mysql2 returns a ResultSetHeader as rowsOrResult (not an array).
            // For SELECT, rowsOrResult is the rows array and maybeHeader is FieldPacket[].
            if (!Array.isArray(rowsOrResult) && rowsOrResult != null && 'affectedRows' in rowsOrResult) {
                affectedRows = (rowsOrResult as ResultSetHeader).affectedRows;
            } else if (maybeHeader && !Array.isArray(maybeHeader) && 'affectedRows' in maybeHeader) {
                affectedRows = maybeHeader.affectedRows;
            } else if (rows.length > 0) {
                affectedRows = rows.length;
            }

            return { rows, affectedRows };
        } catch (error) {
            // Standalone query: roll back its throwaway connection. Pinned (transaction) connection:
            // leave the ROLLBACK to runTransaction so the whole transaction aborts on this connection.
            if (!pinned && conn) { try { await conn.query("ROLLBACK;"); } catch { /* autocommit: nothing to roll back */ } }
            throw error;
        } finally {
            if (!pinned && conn) conn.release();
        }
    }

    getCreateSchemaQuery(schemaName: string): QueryInput {
        return { query: `CREATE SCHEMA IF NOT EXISTS ${escapeIdentifier(schemaName, "mysql")};` };
    }

    getCheckSchemaQuery(schemaName: string | string[]): QueryInput {
        if (Array.isArray(schemaName)) {
            return { query: `SELECT ${schemaName
                .map(
                    (db) =>
                        `(CASE WHEN EXISTS (SELECT NULL FROM INFORMATION_SCHEMA.SCHEMATA WHERE SCHEMA_NAME = ${escapeLiteral(db, "mysql")}) THEN 1 ELSE 0 END) AS ${escapeIdentifier(db, "mysql")}`
                )
                .join(", ")};`};
        }
        return { query: `SELECT (CASE WHEN EXISTS (SELECT NULL FROM INFORMATION_SCHEMA.SCHEMATA WHERE SCHEMA_NAME = ${escapeLiteral(schemaName, "mysql")}) THEN 1 ELSE 0 END) AS ${escapeIdentifier(schemaName, "mysql")};`};
    }

    getCreateTableQuery(table: string, headers: MetadataHeader): QueryInput[] {
        return MySQLTableQueryBuilder.getCreateTableQuery(table, headers, this.getConfig());
    }

    async getAlterTableQuery(table: string, alterTableChangesOrOldHeaders: AlterTableChanges | MetadataHeader, newHeaders?: MetadataHeader): Promise<QueryInput[]> {
        let alterTableChanges: AlterTableChanges;
        let updatedMetaData: MetadataHeader
        // Staging temp tables are throwaway CREATE TABLE AS SELECT intermediaries (columns only, no
        // keys). Reconciling a PK would emit DROP/ADD PRIMARY KEY against a keyless table, which
        // errors — so skip PK reconciliation for them (keyed off the staging-name prefix).
        const stagingPrefix = this.getConfig().stagingPrefix ?? "temp_staging__";
        const isStagingTable = table.startsWith(stagingPrefix);
        const alterPrimaryKey = (this.config.updatePrimaryKey ?? false) && !isStagingTable;
        if (isMetadataHeader(alterTableChangesOrOldHeaders)) {
            // If old headers are provided in MetadataHeader format, compare them with newHeaders
            if (!newHeaders) {
                throw new Error("Missing new headers for ALTER TABLE query");
            }
            ({ changes: alterTableChanges, updatedMetaData }  = compareMetaData(alterTableChangesOrOldHeaders, newHeaders, this.getDialectConfig(), this.config.logger));
            this.updateTableMetadata(table, updatedMetaData, "metaData")
        } else {
            alterTableChanges = alterTableChangesOrOldHeaders;
        }
        const queries: QueryInput[] = [];
        const schemaPrefix = this.getConfig().schema ? `${escapeIdentifier(this.getConfig().schema!, "mysql")}.` : "";

        // R9: surface schema changes that are computed but blocked by the safe-default flags.
        if (!isStagingTable) this.warnBlockedSchemaChanges(table, alterTableChanges);

        if (alterTableChanges.primaryKeyChanges.length > 0 && alterPrimaryKey) {
            queries.push(this.getDropPrimaryKeyQuery(table));
        }

        // Only drop the unique when the caller opted in (A10); off (default) keeps it and the load
        // fails loud / diverts on the collision. warnBlockedSchemaChanges emits the warning.
        if (alterTableChanges.noLongerUnique.length > 0 && this.getConfig().dropUniqueConstraints) {
            const uniqueIndexesResult = await this.runQuery(this.getUniqueIndexesQuery(table));

            if (!uniqueIndexesResult.success || !uniqueIndexesResult.results) {
                throw new Error(`Failed to fetch unique indexes for table ${table}: ${uniqueIndexesResult.error}`);
            }
        
            const uniqueIndexes = (uniqueIndexesResult.results || [])
                .map(row => normalizeResultKeys(row))
                .filter(row => row.columns);
        
            const indexesToDrop = uniqueIndexes
                .filter(({ columns }) => columns.split(", ").some((col: string) => alterTableChanges.noLongerUnique.includes(col)))
                .map(({ index_name }) => `DROP INDEX ${escapeIdentifier(index_name, "mysql")}`);
        
            if (indexesToDrop.length > 0) {
                queries.push({
                    query: `ALTER TABLE ${schemaPrefix}${escapeIdentifier(table, "mysql")} ${indexesToDrop.join(", ")};`,
                    params: []
                });
            }
        }
        
        const alterQueries = MySQLTableQueryBuilder.getAlterTableQuery(table, alterTableChanges, this.getConfig().schema, this.getConfig());
        queries.push(...alterQueries);
        if (alterTableChanges.primaryKeyChanges.length > 0 && alterPrimaryKey) {
            queries.push(this.getAddPrimaryKeyQuery(table, alterTableChanges.primaryKeyChanges));
        }
        return queries;
    }

    /**
     * R8: detect text columns whose charset differs from the target (`charset`, default utf8mb4) and,
     * if any, return one `CONVERT TO CHARACTER SET` statement. Numeric/date columns have a NULL
     * `CHARACTER_SET_NAME` and are ignored. Convergent: once all text columns match, returns `[]`.
     */
    public async getCharsetUpgradeQueries(table: string): Promise<QueryInput[]> {
        const targetCharset = this.config.charset || DIALECT_CONFIG.charset;
        const targetCollate = this.config.collate || DIALECT_CONFIG.collate;
        // charset/collate are config-derived identifiers, not row data — validate before
        // interpolating (they can't be parameter-bound in a CONVERT clause).
        const idOk = /^[A-Za-z0-9_]+$/;
        if (!idOk.test(targetCharset) || !idOk.test(targetCollate)) {
            throw new Error(`Invalid charset/collate for upgrade: ${JSON.stringify({ targetCharset, targetCollate })}`);
        }
        const schema = this.getConfig().schema;
        const detect: QueryInput = {
            query:
                `SELECT COUNT(*) AS c FROM information_schema.COLUMNS ` +
                `WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ? ` +
                `AND CHARACTER_SET_NAME IS NOT NULL AND CHARACTER_SET_NAME <> ?`,
            params: [schema, table, targetCharset],
        };
        const res = await this.runQuery(detect);
        const count = Number(Object.values(res.results?.[0] ?? { c: 0 })[0] ?? 0);
        if (!count) return [];
        const schemaPrefix = schema ? `${escapeIdentifier(schema, "mysql")}.` : "";
        return [{
            query: `ALTER TABLE ${schemaPrefix}${escapeIdentifier(table, "mysql")} CONVERT TO CHARACTER SET ${targetCharset} COLLATE ${targetCollate};`,
            params: [],
        }];
    }

    getDropTableQuery(table: string): QueryInput {
        return MySQLTableQueryBuilder.getDropTableQuery(table, this.getConfig().schema);
    }

    getTableExistsQuery(schema: string, table: string): QueryInput {
        return MySQLTableQueryBuilder.getTableExistsQuery(schema, table);
    }

    getTableMetaDataQuery(schema: string, table: string): QueryInput {
        return MySQLTableQueryBuilder.getTableMetaDataQuery(schema, table);
    }

    getPrimaryKeysQuery(table: string): QueryInput {
        return MySQLIndexQueryBuilder.getPrimaryKeysQuery(table, this.getConfig().schema);
    }

    getForeignKeyConstraintsQuery(table: string): QueryInput {
        return MySQLIndexQueryBuilder.getForeignKeyConstraintsQuery(table, this.getConfig().schema);
    }

    getViewDependenciesQuery(table: string): QueryInput {
        return MySQLIndexQueryBuilder.getViewDependenciesQuery(table, this.getConfig().schema);
    }

    getDropPrimaryKeyQuery(table: string): QueryInput {
        return MySQLIndexQueryBuilder.getDropPrimaryKeyQuery(table, this.getConfig().schema);
    }

    getDropUniqueConstraintQuery(table: string, indexName: string): QueryInput {
        return MySQLIndexQueryBuilder.getDropUniqueConstraintQuery(table, indexName, this.getConfig().schema);
    }

    getAddPrimaryKeyQuery(table: string, primaryKeys: string[]): QueryInput {
        return MySQLIndexQueryBuilder.getAddPrimaryKeyQuery(table, primaryKeys, this.getConfig().schema);
    }

    getUniqueIndexesQuery(table: string, column_name?: string): QueryInput {
        return MySQLIndexQueryBuilder.getUniqueIndexesQuery(table, column_name, this.getConfig().schema);
    }

    getSplitTablesQuery(table: string): QueryInput {
        return MySQLTableQueryBuilder.getSplitTablesQuery(table, this.getConfig().schema);
    }

    getInsertStatementQuery(tableOrInput: string | InsertInput, data?: Record<string, any>[], metaData?: MetadataHeader, insertInput?: "UPDATE"|"INSERT"): QueryInput {
        return MySQLInsertQueryBuilder.getInsertStatementQuery(tableOrInput, data, metaData, this.getConfig(), insertInput)
    }

    getInsertFromStagingQuery(tableOrInput: string | InsertInput, metaData?: MetadataHeader, insertInput?: "UPDATE"|"INSERT", pkFilter?: Record<string, any>): QueryInput {
        return MySQLInsertQueryBuilder.getInsertFromStagingQuery(tableOrInput, metaData, this.getConfig(), insertInput, pkFilter)
    }

    getInsertChangedRowsToHistoryQuery(tableOrInput: string | InsertInput, metaData?: MetadataHeader, pkFilter?: Record<string, any>): QueryInput {
        return MySQLInsertQueryBuilder.getInsertChangedRowsToHistoryQuery(tableOrInput, metaData, this.getConfig(), pkFilter)
    }

    getCreateTempTableQuery(table: string, stagingPrefix?: string): QueryInput {
        return MySQLTableQueryBuilder.getCreateTempTableQuery(table, this.getConfig().schema, stagingPrefix)
    }

    getConstraintConflictQuery(table: string, structure: { uniques: Record<string, string[]>; primary: string[] }, stagingPrefix?: string): QueryInput {
        return MySQLIndexQueryBuilder.generateConstraintConflictBreakdownQuery(table, structure, this.getConfig().schema, stagingPrefix)
    }
